    ["_CeladonMansion3FGameDesignerText"] = "Kan du lide\nspillet?\nJeg har designet\nspillet!\nSelvom det er\nmeget besværligt\nat fuldføre\nPOKéDEXEN: Giv\nikke op!\nVis mig den,\nnår den er\nkomplet!",
    ["_CeladonMansion3FGameProgramPCText"] = "Programkoden!\nDet er bedst at\nholde fingrene\nvæk fra den!",
    ["_CeladonMansion3FGameScriptPCText"] = "Manuskriptet!\nJeg bør nok\nikke kigge på\nslutningen!",
    ["_CeladonMansion3FGraphicArtistText"] = "Jeg er\ngrafikeren!\nJeg har tegnet\ndet hele!",
    ["_CeladonMansion3FPlayingGamePCText"] = "Der spiller\nnogen i stedet\nfor at arbejde!",
    ["_CeladonMansion3FProgrammerText"] = "Mig? Jeg er\nprogrammøren!",
    ["_CeladonMansion3FWriterText"] = "Historien er\nfra mig!\nEr ERIKA ikke\nsød?\nMen jeg kan også\ngodt lide MISTY!\nOg ikke at\nglemme,\nSABRINA!",
    ["_CeladonMansionRoofHouseHikerText"] = "Jeg kender hver\nenkelt detalje af\nPOKéMON-VERDENEN\ni din\nGAME BOY!\nMød venner og\nbyt POKéMON!",
    ["_CeladonMansionRoofHouseSignText"] = "JEG VED ALT!",
    ["_CeladonMart1FCurrentFloorSignText"] = "STUEN: KUNDE-\nINFORMATION",
    ["_CeladonMart1FDirectorySignText"] = "STUEN: KUNDE-\nINFORMATION\n1. SAL: UDSTYR\nTIL TRÆNERE\n2. SAL: VIDEOSPIL\n3. SAL: GAVE-\nARTIKLER\n4. SAL: DROGERI\nTAGHAVE:\nAUTOMATER",
    ["_CeladonMart1FReceptionistText"] = "Velkommen til\nSTORCENTERET i\nCELADON\nCITY!\nPå tavlen til\nhøjre finder du\nen oversigt.",
    ["_CeladonMart2FCurrentFloorSignText"] = "Nyttige items\nfor trænere!\n1. SAL: UDSTYR\nTIL TRÆNERE",
    ["_CeladonMart2FGirlText"] = "Før længere\nture bør du\nkøbe REVIVER.",
    ["_CeladonMart2FMiddleAgedManText"] = "SUPERSKJOLD\nholder POKéMON\npå afstand...\nDet er bedre end\nalmindeligt\nSKJOLD!",
    ["_CeladonMart3FClerkReceivedTM18Text"] = "{PLAYER} modtager\n{RAM:wStringBuffer}!",
    ["_CeladonMart3FClerkTM18ExplanationText"] = "TM18 er KONTER!\nJeg har alligevel\nikke brug for\nTM'en her!",
    ["_CeladonMart3FClerkTM18NoRoomText"] = "Din rygsæk\ner for fuld!",
    ["_CeladonMart3FClerkTM18PreReceiveText"] = "Hej! Jeg har\nlige spillet\nPOKéMON\nfærdig!\nEr du ikke der\nendnu?\nMåske hjælper\ndet her dig!",
    ["_CeladonMart3FCurrentFloorSignText"] = "2. SAL: VIDEOSPIL-\nBUTIK",
    ["_CeladonMart3FFightingGameText"] = "Et kampsports-\nspil! Spændende!",
    ["_CeladonMart3FGameBoyKid1Text"] = "Hvert fanget\nPOKéMON får\net ID-nr. og\nregistreres med\nnavnet på\nORIGINALTRÆNEREN,\nOT.\nOT'en er den\ntræner, der har\nfanget\nPOKéMONen!",
    ["_CeladonMart3FGameBoyKid2Text"] = "Cool!\nMin kammerat\nbytter sin\nKANGASKHAN for\nmin GRAVELER!",
    ["_CeladonMart3FGameBoyKid3Text"] = "Kom, GRAVELER!\nJeg er\nGRAVELER-samler!\nHvad nu?\nGRAVELER har\nudviklet sig til\net andet\nPOKéMON!",
    ["_CeladonMart3FLittleBoyText"] = "Ud fra deres\nID-nr. kan du\ngenkende POKéMON,\nsom du har\nmodtaget ved\net bytte!",
    ["_CeladonMart3FPokemonPosterText"] = "Den røde og den\nblå POKéMON-\nudgave! Cool!",
    ["_CeladonMart3FPuzzleGameText"] = "Et puslespil!\nDet er sikkert\nfængende!",
    ["_CeladonMart3FRPGText"] = "Et rollespil!\nJeg har ikke\ntid! Ærgerligt!",
    ["_CeladonMart3FSNESText"] = "Det er en\nSUPER NINTENDO!",
    ["_CeladonMart3FSportsGameText"] = "Et racerspil!\nDet ville min\nfar kunne lide!",
    ["_CeladonMart4FCurrentFloorSignText"] = "Gør andre glade\nmed gaver!\n3. SAL: GAVE-\nARTIKLER\nTILBUD!\nSærpriser på\nELEMENT-STEN!",
    ["_CeladonMart4FSuperNerdText"] = "Jeg køber en\nPOKéDUKKE til\nmin kæreste!",
    ["_CeladonMart4FYoungsterText"] = "Jeg har fået\net tip!\nDu kan flygte\nfra vilde POKéMON,\nhvis du\ndistraherer dem\nmed en\nPOKéDUKKE!",
    ["_CeladonMart5FCurrentFloorSignText"] = "4. SAL: DROGERI",
    ["_CeladonMart5FGentlemanText"] = "Kun her kan\ndu købe\npræstationsfremmende\nmidler til\ndine POKéMON!\nCALCIUM øger\nstyrken af\nSPECIAL-ANGREB!\nCARBON øger\nINITIATIVET.",
    ["_CeladonMart5FSailorText"] = "Jeg er her på\ngrund af de\npræstationsfremmende\nmidler til\nPOKéMON.\nPROTEIN øger\nANGREBS-\nSTYRKEN.\nJERN styrker\nFORSVARET!",
    ["_CeladonMartRoofCurrentFloorSignText"] = "TAGHAVE:\nAUTOMATER",
    ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "Jeg er tørstig!\nJeg vil gerne\ndrikke noget!\nVil du give\npigen en\ndrik?",
    ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "Hvilken drik\nvil du give\nhende?",
    ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "Det er sødt\nment, men jeg\ner ikke\ntørstig!",
    ["_CeladonMartRoofLittleGirlImThirstyText"] = "Jeg er tørstig!\nEt kongerige\nfor en drik!",
    ["_CeladonMartRoofLittleGirlNoRoomText"] = "Du har ikke\nplads til det!",
    ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "{PLAYER} modtager\n{RAM:wStringBuffer}!",
    ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "{PLAYER} modtager\n{RAM:wStringBuffer}!",
    ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "{PLAYER} modtager\nTM49!",
    ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "\n{RAM:wStringBuffer} er\nISSTRÅLE!\nMed den kan man\nfryse visse\nmodstandere!",
    ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "\n{RAM:wStringBuffer} er\nSTENHAGL!\nMed den kan man\nskræmme visse\nmodstandere!",
    ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "\nTM49 er\nTRIPLET!",
    ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "Ja!\nKILDEVAND!\nMange tak!\nTag venligst\nden her gave!",
    ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "Cool!\nLIMONADE!\nMange tak!\nTag venligst\nden her gave!",
    ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "Cool!\nSODAVAND!\nMange tak!\nTag venligst\nden her gave!",
    ["_CeladonMartRoofSuperNerdText"] = "Tro det eller\nej: Min\nsøster er\nen træner!\nMen hun er så\nbarnlig! Jeg\nbliver helt\nskør af det!",
    ["_CeladonPokecenterBeautyText"] = "Jeg cyklede\nherop fra\nFUCHSIA CITY\nad CYKELSTIEN!",
    ["_CeladonPokecenterGentlemanText"] = "POKéFLØJTEN\nvækker POKéMON\nmed en lyd,\nsom kun POKéMON\nkan høre!",
    ["_CeruleanBadgeHouseBoulderBadgeText"] = "Dine POKéMONs\nANGREB\nstyrkes en\nsmule.\nDesuden kan\ndu til enhver tid\nbruge BLITZ.",
    ["_CeruleanBadgeHouseCascadeBadgeText"] = "POKéMON op til\nlevel 30 følger\ndine ordrer!\nPOKéMON af\nhøjere level\nadlyder dig\ndog ikke!\nEndvidere kan du\nbruge SKÆRER\nuden for\nkampe!",
    ["_CeruleanBadgeHouseEarthBadgeText"] = "Ethvert POKéMON\nadlyder dig!",
    ["_CeruleanBadgeHouseMarshBadgeText"] = "POKéMON op til\nlevel 70 følger\ndine ordrer.\nPOKéMON af\nhøjere level\nadlyder dig\ndog ikke!",
    ["_CeruleanBadgeHouseMiddleAgedManText"] = "Kun meget dygtige\ntrænere bærer\nPOKéMON-ORDENER.\nSom jeg kan se,\nbærer du\nallerede en\nORDEN.\nORDENERNE er\nomgivet af\nmystik!",
    ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "Besøg mig,\nnår du vil.",
    ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "Nå, lad mig se...\nOm hvilken af de\notte ORDENER\nskal jeg fortælle\ndig noget?",
    ["_CeruleanBadgeHouseRainbowBadgeText"] = "POKéMON op til\nlevel 50 følger\ndine ordrer.\nPOKéMON af\nhøjere level\nadlyder dig\ndog ikke!\nDerudover kan\ndu bruge STYRKE\nuden for\nkampe.",
    ["_CeruleanBadgeHouseSoulBadgeText"] = "Dine POKéMONs\nFORSVAR\nforbedres.\nEndvidere kan du\nbruge SURFER\nuden for\nkampe.",
    ["_CeruleanBadgeHouseThunderBadgeText"] = "Dine POKéMONs\nINITIATIV\nøges.\nDesuden er\ndet muligt for\ndig at bruge\nFLYVE uden for\nkampe.",
    ["_CeruleanBadgeHouseVolcanoBadgeText"] = "Dine POKéMONs\nSPECIAL-\nEGENSKABER\nøges.",
    ["_CeruleanCityBikeShopSign"] = "CYKELBUTIKKEN\nCykl let og\nhurtigt gennem\nhuler og\ngræs!",
    ["_CeruleanCityCooltrainerF1SlowbroPunchText"] = "SLOWBRO, slå\ntil! Åh nej!\nIkke igen...",
    ["_CeruleanCityCooltrainerF1SlowbroUseSonicboomText"] = "OK! SLOWBRO!\nBrug ULTRALYD!\nKom nu, gør\ndet, SLOWBRO!",
    ["_CeruleanCityCooltrainerF1SlowbroWithdrawText"] = "SLOWBRO, TILBAGE!\nNej, ikke!!!\nDet er svært at\nstyre en POKéMON!\nOm dit POKéMON\nadlyder, afhænger\naf dine\nevner som\ntræner!",
    ["_CeruleanCityCooltrainerF2Text"] = "Jeg ville gerne\nhave en rød\nCYKEL!\nMen jeg ville\naldrig køre på\nden, så den\nikke bliver\nbeskidt!",
    ["_CeruleanCityCooltrainerMText"] = "Er du også en\ntræner? At\nsamle og\nkæmpe er ikke\naltid let!",
    ["_CeruleanCityGuardText"] = "Folkene her\nblev bestjålet.\nTEAM ROCKET\nstår bag de\nafskyelige\nforbrydelser!\nSelv POLITIET\ner magtesløst\nover for TEAM\nROCKET!",
    ["_CeruleanCityGymSign"] = "CERULEAN CITY\nPKMN-ARENA\nARENALEDER: \nMISTY\nDen uhyggelige\narenaleder!",
    ["_CeruleanCityRivalDefeatedText"] = "Hey,\nrolig nu! Du\nhar vundet!",
    ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}: Skal\njeg fortælle\ndig noget?\nJeg var hos BILL\nog fik vist\nhans sjældne\nPOKéMON!\nDet gav mig\nnogle nye\nindførsler i min\nPOKéDEX!\nBILL er verdens-\nkendt som\nPOKéMANIAK!\nHan har\nudviklet\nPOKéMON-\nopbevaringssystemet\ntil PC'en!\nDu kan takke\nham for det!\nNå, jeg smutter!\nVi ses!",
    ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}: Hej,\n{PLAYER}!\nSå du er stadig\npå farten!\nJeg har det\nfint! Jeg har\nfanget masser af\nnye, stærke\nPOKéMON!\nVis mig, hvad du\nhar fanget,\n{PLAYER}!",
    ["_CeruleanCityRivalVictoryText"] = "Ha!\nDu har intet at\nstille op mod\nmin genialitet!",
    ["_CeruleanCityRocketIBetterGetMovingText"] = "\nJeg går nok\nbedre! Farvel!",
    ["_CeruleanCityRocketIGiveUpText"] = "Fint nok!\nJeg giver op!\nJeg forsvinder!",
    ["_CeruleanCityRocketIllReturnTheTMText"] = "OK! Jeg giver\nden stjålne TM\ntilbage!",
    ["_CeruleanCityRocketReceivedTM28Text"] = "{PLAYER} modtager\nTM28!",
    ["_CeruleanCityRocketTM28NoRoomText"] = "Skaf plads til\ndenne seje\nitem!\nJeg kan ikke gå,\nfør jeg har\ngivet dig\nden!",
    ["_CeruleanCityRocketText"] = "Hey! Bliv\nudenfor! Du har\nikke noget at\ngøre her! Hvad\nlaver jeg her?\nJeg er bare en\nuskyldig\nforbipasserende! Hvad?\nTror du mig\nikke?",
    ["_CeruleanCitySignText"] = "CERULEAN CITY.\nEn mystisk\nblå aura\nomgiver byen!",
    ["_CeruleanCitySlowbroIgnoredOrdersText"] = "SLOWBRO ignorerer\nordrerne...",
    ["_CeruleanCitySlowbroIsLoafingAroundText"] = "SLOWBRO driver\nrundt...",
    ["_CeruleanCitySlowbroTookASnoozeText"] = "SLOWBRO tager\nsig en lur...",
    ["_CeruleanCitySlowbroTurnedAwayText"] = "SLOWBRO vender\nsig bort...",
    ["_CeruleanCitySuperNerd1Text"] = "Busken foran\nbutikken er i\nvejen!\nMåske findes der\nen anden vej!?",
    ["_CeruleanCitySuperNerd2Text"] = "Laver du et\nleksikon over\nPOKéMON? Det\nlyder sjovt!",
    ["_CeruleanCitySuperNerd3Text"] = "CERULEAN\nHULEN! Der bor\nekstremt stærke\nPOKéMON!\nKun PKMN-LIGA-\nmestre har\nadgang!",
    ["_CeruleanCityTrainerTipsText"] = "TIPS TIL TRÆNERE\nTrykker man på\nB-knappen under\net POKéMONs\nudvikling, så\nafbrydes\nprocessen!",
    ["_CeruleanGymAfterBattleText1"] = "Du skal stille\nop mod andre\ntrænere for at\nfinde ud af,\nhvor god du er.",
    ["_CeruleanGymAfterBattleText2"] = "MISTY forbedrer\nkonstant sine\nevner!\nEn som dig har\ningen chance for\nat besejre hende!",
    ["_CeruleanGymBattleText1"] = "Først udfordrer\njeg dig!\nMISTY må vente!",
    ["_CeruleanGymBattleText2"] = "Plask!\nJeg er din\nførste modstander!\nSå går det løs!",
    ["_CeruleanGymEndBattleText1"] = "Jeg\ner overvældet!",
    ["_CeruleanGymEndBattleText2"] = "\nDet kan ikke\nvære sandt!",
    ["_CeruleanGymGymGuideBeatMistyText"] = "Du har besejret\nMISTY! Sagde jeg\ndet ikke?\nTro mig, vi\ndanner et rigtig\ngodt team!",
    ["_CeruleanGymGymGuideChampInMakingText"] = "Hey! Vent, du\nkommende champion!\nJeg har et\ntip til dig!\nMISTY,\nARENALEDEREN,\nkæmper med\nVAND-POKéMON!\nDu kan trække\nvandet fra dem\nmed PLANTE-\nPOKéMON!\nELEKTRO-POKéMON\nkunne også\nvise sig\nnyttige!",
    ["_CeruleanGymMistyCascadeBadgeInfoText"] = "KILDE-ORDENEN\nfår alle POKéMON\nop til level 30\ntil at adlyde\ndine ordrer!\nSelv de stædige\nadlyder dig!\nDine POKéMON\nkan nu bruge\nSKÆRER når som\nhelst!\nDu kan hugge\nsmå buske ned\nog dermed bane\nnye veje!\nTil sidst\nforærer jeg dig\nmin\nyndlings-TM!",
    ["_CeruleanGymMistyPreBattleText"] = "Du må være ny,\nfor jeg har\naldrig set dig\nfør!\nHvis en træner\nvil blive proff,\nskal han\nudarbejde en\nPOKéMON-taktik!\nHvordan\nfanger du dine\nPOKéMON?\nMin strategi\nbygger på\nnådesløs\noffensiv brug\naf VAND-\nPOKéMON!",
    ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "Wow! Du\ner virkelig god!\nGodt så!\nJeg overlader\ndig KILDE-ORDENEN\nsom tegn på\ndin triumf!",
    ["_CeruleanGymMistyReceivedTM11Text"] = "{PLAYER} modtager\nTM11!",
    ["_CeruleanGymMistyTM11ExplanationText"] = "TM11 er\nBOBLESTRÅLE!\nVAND-POKéMON\nkan lære denne\nattack!",
    ["_CeruleanGymMistyTM11NoRoomText"] = "Du har ikke\nplads til min\ngave lige nu!",
    ["_CeruleanMartCooltrainerFText"] = "Har du\nSÆRBOLSJER?\nGiver man en\nPOKéMON et\nBOLSJE, opnår\ndet næste\nlevel!",
    ["_CeruleanMartCooltrainerMText"] = "Brug et\nSKJOLD til at\nholde insekter\nog svagere\nPOKéMON væk\nfra dig!\nFor optimal\nbeskyttelse bør\ndu sætte det\nstærkeste POKéMON\nøverst på\nlisten!",
    ["_CeruleanPokecenterGentlemanText"] = "Har nogen\nfortalt dig om BILL?\nAlle kalder ham\nPOKéMANIAKEN!\nMen jeg tror,\nfolk bare er\nmisundelige på\nBILL.\nHvem ville ikke\nprale med sine\nPOKéMON?",
    ["_CeruleanPokecenterGuyText"] = "BILL ejer\nmange POKéMON!\nHan har nogle\nmeget sjældne i\nsin samling!",
    ["_CeruleanPokecenterSuperNerdText"] = "Denne BILL!\nJeg hørte, han\nville gøre alt\nfor sjældne\nPOKéMON!",
    ["_CeruleanTradeHouseGrannyText"] = "Min mand bytter\ngerne POKéMON\nlivet igennem.\nEr du også en\nsamler? Vil du\nbytte POKéMON\nmed ham?",
    ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "Det gemene\nTEAM ROCKET!\nHør, hvad de\nhar begået\ndenne gang!\nDe har stjålet\nSKUFFER, en\nTM, som lærer\nPOKéMON at grave\nhuller!\nSKUFFER var\nsyndig dyr!",
    ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "Det, der er væk,\ner væk!\nJeg lærer DIGLETT\nat grave uden\nSKUFFER!",
    ["_CeruleanTrashedHouseGirlText"] = "TEAM ROCKET\nhar sikkert brug\nfor SKUFFER til\nen eller anden\nskændsel!",
    ["_CeruleanTrashedHouseWallHoleText"] = "TEAM ROCKET\nhar efterladt\nspor!",
    ["_ChampionsRoomOakComeWithMeText"] = "OAK: {PLAYER}!\nDu har\nforstået, at din\nsejr ikke\nudelukkende var\ndin egen\nfortjeneste!\nForholdet\ntil dine POKéMON\ner eksemplarisk!\n{PLAYER}!\nFølg mig!",
    ["_ChampionsRoomOakCongratulatesPlayerText"] = "OAK: Så du\nhar altså vundet!\nTillykke!\nDu er den nye\nchampion i\nPKMN-LIGAEN!\nDu har lært\nmeget, siden\ndu drog af sted\nmed\n{RAM:wNameBuffer}!\n{PLAYER},\ndu er allerede\nmeget mere\nerfaren!",
    ["_ChampionsRoomOakDisappointedWithRivalText"] = "OAK: {RIVAL}!\nDu har skuffet\nmig meget!\nDa jeg hørte,\ndu havde besejret\nTOP FIRE, kom\njeg herhen!\nMen da jeg\nankom, var du\ntaberen!\n{RIVAL}, ved\ndu, hvorfor du\ntabte?\nDu har ikke\ngivet dine\nPOKéMON nok\nkærlighed og\ntillid!\nSådan bliver\ndu aldrig\nen sejrherre!",
    ["_ChampionsRoomOakText"] = "OAK: {PLAYER}!",
    ["_ChampionsRoomRivalAfterBattleText"] = "Hvorfor? Hvorfor\ntabte jeg?\nJeg har dog\nopdraget mine\nPOKéMON meget\nomhyggeligt...\nPokkers!\nDu er den nye\nCHAMPION i\nPKMN-LIGAEN!\nMen det under\njeg dig ikke!",
    ["_ChampionsRoomRivalIntroText"] = "{RIVAL}: Hej!\nJeg har ventet\nlænge på dette\nøjeblik,\n{PLAYER}!\nJeg har brug for\nen stærk\nmodstander for\nat holde formen\nved lige!\nMens jeg\nopdaterede min\nPOKéDEX,\nudvalgte jeg kun\nde stærkeste\nPOKéMON!\nMen ikke kun\ndet: Jeg har\nopbygget teams,\nder kan besejre\nALLE POKéMON!\nOg nu...\n...er jeg\nchampion i\nPKMN-LIGAEN!\n{PLAYER}!\nVed du, hvad\ndet betyder?\nJeg vil sige\ndig det!\nJeg er verdens\nmest magtfulde\ntræner!",
    ["_ChanseyDexEntry"] = "En svær at\nfange,\nsjælden POKéMON.\nDen giver\nsin fanger\nmeget glæde.",
    ["_ChargeMoveEffectText"] = "{USER}",
    ["_CharizardDexEntry"] = "Denne POKéMON\nkan smelte klipper\nmed sin ildånde.\nDet forårsager\nen gang imellem\nskovbrande.",
    ["_CharmanderDexEntry"] = "Denne POKéMON\nforetrækker varme\nlevesteder.\nI regnvejr damper\nspidsen af CHARMANDERs\nhale.",
    ["_CharmeleonDexEntry"] = "Når CHARMELEON\nsvinger med sin\nhale, stiger\ntemperaturen\ntil enorme\nhøjder.",
    ["_ChooseABoxText"] = "Vælg en\nPOKéMON-BOKS!",
    ["_CinnabarGymBlainePostBattleAdviceText"] = "ILDSTORM er\ndet kraftigste\nildangreb!\nMen det er\nmagtesløst over\nfor VAND-\nPOKéMON!",
    ["_CinnabarGymBlainePreBattleText"] = "Haha!\nJeg er BLAINE,\nARENALEDEREN på\nCINNOBER-ØEN!\nMine ILD-\nPOKéMON sætter\nmine modstanderes\nsejrsdrømme i\nbrand!\nDu burde nok\nhave ILDHELBREDER\nklar!",
    ["_CinnabarGymBlaineReceivedTM38Text"] = "{PLAYER} modtager\n{RAM:wStringBuffer}!",
    ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "Min ild\ner slukket!\nDu har fortjent\nVULKAN-ORDENEN\nærligt",
    ["_CinnabarGymBlaineTM38ExplanationText"] = "\nTM38 er\nILDSTORM!\nILD-POKéMON\nkan lære denne\nattack!\nCHARMELEON og\nPONYTA er\nprædestineret\ntil det!",
    ["_CinnabarGymBlaineTM38NoRoomText"] = "Skaf plads til\nmin gave!",
    ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "Haha!\nVULKAN-ORDENEN\nøger dine\nPOKéMONs\nSPECIAL-\nEGENSKABER!\nTag også\ndenne gave!",
    ["_CinnabarGymGymGuideBeatBlaineText"] = "{PLAYER}! Du har\nbrændemærket\nurostifteren!",
    ["_CinnabarGymGymGuideChampInMakingText"] = "Hey! Vent, du\nkommende champion!\nDen hidsige\nBLAINE er en\nILD-POKéMON-\nspecialist!\nDu burde\nafkøle hans\ntemperament med\nvand!\nOg skaf dig\nILDHELBREDER!",
    ["_CinnabarGymQuizCorrectText"] = "Og svaret\ner... RIGTIGT!\nGå videre!",
    ["_CinnabarGymQuizIncorrectText"] = "FORKERT!\nSikke uheld!",
