    ["_LavenderMartBaldingGuyText"] = "Jeg leder efter\nitems, der\nforbedrer mine\nPOKéMONs\nevner under\nen kamp!\nFor eksempel\nX-ANGREB,\nX-FORSVAR, X-TEMPO\nog X-SPECIAL.\nVed du, hvor jeg\nkan købe dem?",
    ["_LavenderMartCooltrainerMNuggetText"] = "Jeg fandt en\nGULDKLUMP i\nbjergene.\nJeg troede,\nden var ubrugelig,\nmen så fik\njeg ¥5000\nfor den!",
    ["_LavenderMartCooltrainerMReviveText"] = "Kender du\nREVIVEREN? Med\nden kan du give\nbesejrede POKéMON\nkræfterne\ntilbage!",
    ["_LavenderPokecenterGentlemanText"] = "TEAM ROCKET\nville gøre alt\nfor guld!",
    ["_LavenderPokecenterGuyText"] = "CUBONE bærer\nkraniemasker!\nMan betaler en\nmasse penge for dem!",
