    ["_Museum1FScientist1ThankYouText"] = "OK, det bliver ¥50!\nMange tak!",
    ["_Museum1FScientist1TheresALabSomewhereText"] = "Der skal findes\net laboratorium,\nhvor man\nforsøger at\nvække URTIDS-\nPOKéMON til\nlive fra gammelt\nRAV!",
    ["_Museum1FScientist1WouldYouLikeToComeInText"] = "For børn koster\nadgangen ¥50!\nVil du\nkomme ind?",
    ["_Museum1FScientist2GetTheOldAmberCheckText"] = "Pst! Lad\nGAMMELT RAV\nblive undersøgt!",
    ["_Museum1FScientist2ReceivedOldAmberText"] = "{PLAYER} modtager\net\nGAMMELT RAV!",
    ["_Museum1FScientist2TakeThisToAPokemonLabText"] = "Pst! Jeg tror,\ndette stykke\nRAV indeholder\nPOKéMON-DNA!\nDet ville være\nfantastisk, hvis\nman kunne vække\net POKéMON til\nlive fra det!\nMen mine\nkolleger tager\nmig ikke\nalvorligt!\nKunne du gøre\nnoget for mig?\nLad det blive\nundersøgt på\nPOKéMON-LABORATORIET!",
    ["_Museum1FScientist2YouDontHaveSpaceText"] = "Du har ikke\nplads til flere\nitems!",
    ["_Museum1FScientist3Text"] = "Vores særlige\nstolthed er to\nfossiler af\nyderst sjældne,\nforhistoriske\nPOKéMON!",
    ["_Museum2FBrunetteGirlText"] = "Jeg vil så gerne\nhave en PIKACHU!\nDen er så\nfrygtelig sød!\nMin far skal\nfange mig en!",
    ["_Museum2FGrampsText"] = "Den\n20. juli 1969!\nDen første\nmånelanding!\nTil tv-\nudsendelsen havde\njeg ekstra\nkøbt et\nfarvefjernsyn!",
    ["_Museum2FHikerText"] = "Ja, en PIKACHU!\nJeg lover,\njeg fanger en!",
