    ["_NameRatersHouseNameRaterComeAnyTimeYouLikeText"] = "Kom forbi, når\ndu vil!",
    ["_NameRatersHouseNameRaterGiveItANiceNameText"] = "Kælenavnet er\n{RAM:wNameBuffer}, ikke?\nEt smukt navn!\nKan du stadig\nlide det, eller\nvil du gerne\nændre det?\nHvad vil du?",
    ["_NameRatersHouseNameRaterPokemonHasBeenRenamedText"] = "OK! Dette POKéMONs\nnye navn\ner {RAM:wBuffer}!\nEt endnu\nsmukkere navn\nend før!",
    ["_NameRatersHouseNameRaterWantMeToRateText"] = "Hej! Jeg er\nden officielle\nNAVNE-BEDØMMER!\nSkal jeg\nbedømme dine\nPOKéMONs kælenavne?",
