    ["_NothingToDepositText"] = "Du har ingen\nitems, du kunne\nopbevare.",
    ["_OHKOText"] = "K.O.-TRÆFFER!",
    ["_OKExclamationText"] = "OK!",
    ["_OakLabEmailText"] = "Der er en\ne-mail i postkassen!\n...\nTil alle\nPOKéMON-TRÆNERE!\nPKMN-LIGAENS\nELITE-TRÆNERE\nventer på modige\nudfordrere!\nTag jeres\nstærkeste POKéMON\nmed og vis,\nhvor gode I er!\nPKMN-LIGA-LEDELSEN\nINDIGO-PLATEAUET\nPS.: PROF. OAK,\nvenligst meld\ndig hos os!\n...",
    ["_OakSpeechText1"] = "Hej! Hjertelig\nvelkommen til\nPOKéMONs verden!\nMit navn er\nOAK! Man\nkalder mig\nPOKéMON-\nPROFESSOREN!",
    ["_OakSpeechText2A"] = "Denne verden\nbebos af væsener,\nman kalder\nPOKéMON!",
    ["_OakSpeechText2B"] = "\nFor nogle mennesker\ner POKéMON\nkæledyr, andre\nholder kampe\nmed dem.\nJeg selv...\n...har gjort min\nhobby til mit\nerhverv og\nstuderer POKéMON.",
    ["_OakSpeechText3"] = "{PLAYER}!\nEn utrolig\nrejse ind i\nPOKéMONs verden\nventer dig!\nEn verden fuld af\nunder, eventyr\nog hemmeligheder!\nKort sagt, en\ndrøm går i\nopfyldelse!",
    ["_OaksAideComeBackText"] = "Jeg har\nen god idé.\nKom tilbage, når\ndu ejer {NUM:hOaksAideRequirement, 1, 3} POKéMON.\nJeg gemmer din\ngave til dig.",
    ["_OaksAideGotItemText"] = "{PLAYER} modtager\n{RAM:wOaksAideRewardItemName}!",
    ["_OaksAideHereYouGoText"] = "Super! Du har\nfanget {NUM:hOaksAideNumMonsOwned, 1, 3} forskellige\nPOKéMON!\nSimpelthen\nfantastisk!\nHer, det har du\ntjent ærligt!",
    ["_OaksAideHiText"] = "Hej! Kan du\nhuske mig? Jeg\ner PROF.\nOAKS\nassistent!\nHvis du har\nfanget mindst\n{NUM:hOaksAideRequirement, 1, 3}\nforskellige\nPOKéMON, har jeg\nen gave til\ndig: {RAM:wOaksAideRewardItemName}\nNå, {PLAYER}, \nhar du fanget\n{NUM:hOaksAideRequirement, 1, 3}\nforskellige\nPOKéMON?",
    ["_OaksAideNoRoomText"] = "Åh! Du har\nikke plads lige\nnu til\n{RAM:wOaksAideRewardItemName}.",
    ["_OaksAideUhOhText"] = "Lad mig se...\nÅh! Du har kun\nfanget {NUM:hOaksAideNumMonsOwned, 1, 3}\nforskellige\nPOKéMON!\nDu skal bruge {NUM:hOaksAideRequirement, 1, 3}\nfor at få\ngaven.",
    ["_OaksLabGirlText"] = "PROF. OAK er\nen kapacitet\ninden for POKéMON!\nBlandt POKéMON-\nTRÆNERE nyder\nhan meget stor\nanseelse!",
    ["_OaksLabGivePokeballsExplanationText"] = "\nDukker en vild\nPOKéMON op,\nkan du fange\ndet.\nKast bare en\nPOKéBALL og\nprøv!\nMen det lykkes\nofte ikke.\nEt sundt\nPOKéMON undslipper\nhurtigt! Man skal\nhave lidt\nheld med sig!",
    ["_OaksLabLastMonText"] = "Det er PROF.\nOAKS sidste\nPOKéMON!",
    ["_OaksLabMonEnergeticText"] = "Denne POKéMON\ner virkelig\nfuld af energi!",
    ["_OaksLabOak1ComeSeeMeSometimesText"] = "PROF. OAK:\nBesøg mig fra\ntid til anden.\nDet interesserer\nmig, hvordan din\nPOKéDEX skrider\nfrem.",
    ["_OaksLabOak1DeliverParcelText"] = "PROF. OAK:\nHej, {PLAYER}!\nHvordan har\nPOKéMONen det?\nDet virker til at\nkunne lide dig\nmeget!\nDu må være\nmeget talentfuld\nsom POKéMON-\nTRÆNER!\nHar du noget\ntil mig?\n{PLAYER} overrækker\nPROF. OAK\nPAKKEN.",
    ["_OaksLabOak1HowIsYourPokedexComingText"] = "PROF. OAK:\nDet glæder mig\nat se dig!\nHvordan går det\nmed din\nPOKéDEX? Vis\nmig den lige!",
    ["_OaksLabOak1ParcelThanksText"] = "\nAh! Denne\nSPECIAL-POKéBALL\nhar jeg ventet\nlænge på! \nMange tak!",
    ["_OaksLabOak1PokemonAroundTheWorldText"] = "{PLAYER},\noveralt i denne\nverden venter\nPOKéMON på dig!",
    ["_OaksLabOak1RaiseYourYoungPokemonText"] = "PROF. OAK:\n{PLAYER}, når du\nlader dit POKéMON\nkæmpe, \nbliver det stærkere!",
    ["_OaksLabOak1ReceivedPokeballsText"] = "PROF. OAK:\nDet er ikke nok\nat se POKéMON\nfor at samle\ndetaljerede\noplysninger om\ndem!\nDu skal fange\ndem! Brug denne\nher til at\nindfange vilde\nPOKéMON.\n{PLAYER} modtager\nfem POKéBALLE!",
    ["_OaksLabOak1WhichPokemonDoYouWantText"] = "PROF. OAK: Godt,\n{PLAYER}! Hvilket\nPOKéMON vil\ndu have?",
    ["_OaksLabOak1YourPokemonCanFightText"] = "PROF. OAK: Hvis\ndu møder en vild\nPOKéMON, kan\ndit POKéMON\nkæmpe imod det!",
    ["_OaksLabOak2Text"] = "?",
    ["_OaksLabOakBePatientText"] = "PROF. OAK:\nHav lidt\ntålmodighed, {RIVAL}!\nDu skal også\nhave et!",
    ["_OaksLabOakChooseMonText"] = "PROF. OAK:\n{RIVAL}? Lad mig\ntænke efter...\nAh, rigtigt! I\nskulle jo komme\ntil mig! Vent\net øjeblik!\nHer, {PLAYER}!\nDer ligger tre\nPOKéMON!\nHaha!\nDe befinder\nsig i\nPOKéBALLENE.\nI min ungdom\nvar jeg en\nengageret\nPOKéMON-TRÆNER!\nNu, hvor jeg er\ngammel, har jeg\nkun 3 POKéMON\ntilbage.\nMen jeg giver dig\net af dem! Vælg!",
    ["_OaksLabOakDontGoAwayYetText"] = "PROF. OAK:\nVent lige et\nøjeblik, før du\ngår!",
    ["_OaksLabOakGotPokedexText"] = "PROF. OAK:\n{PLAYER}! {RIVAL}!\nDisse to er\ntil jer!\n{PLAYER} modtager\nen POKéDEX fra\nPROF. OAK!",
    ["_OaksLabOakIHaveARequestText"] = "PROF. OAK:\nÅh ja! Jeg\nhar en stor\nopgave til jer!",
    ["_OaksLabOakMyInventionPokedexText"] = "På bordet\nder ser I\nen opfindelse\naf mig, nemlig\nPOKéDEXEN!\nDen registrerer\nautomatisk data\nom POKéMON,\nman har fanget\neller set!\nDet er en slags\nhigh-tech-leksikon!",
    ["_OaksLabOakThatWasMyDreamText"] = "Et leksikon over\nalle verdens\nPOKéMON...\nDet har altid\nværet min drøm!\nMen jeg er for\ngammel! Jeg kan\nikke klare det\nlængere!\nSå jeg beder\njer om at\nvirkeliggøre\nmin drøm!\nTag af sted,\ndrenge!\nDette er et af\nde mest\nbetydningsfulde\nprojekter i\nPOKéMONs\nhistorie!",
    ["_OaksLabPokedexText"] = "Det ligner et\nleksikon! Men\nsiderne er\nubeskrevne!",
    ["_OaksLabReceivedMonText"] = "{PLAYER} modtager\n{RAM:wNameBuffer}!",
    ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}: Ja! Jeg\ner den bedste!",
    ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}: Bedstefar!\nJeg vil ikke\nvente længere!",
    ["_OaksLabRivalGoAheadAndChooseText"] = "{RIVAL}: Jeg er\nikke så\nutålmodig som\ndig!\nDu må vælge\nførst, {PLAYER}!",
    ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}: Hej\n{PLAYER}! Bedstefar\ner her ikke\nlige nu!",
    ["_OaksLabRivalGrampsText"] = "{RIVAL}: Bedstefar!",
    ["_OaksLabRivalIPickedTheWrongPokemonText"] = "HVAD?\nUmuligt! Jeg\nhar valgt det\nforkerte POKéMON!",
    ["_OaksLabRivalIllTakeThisOneText"] = "{RIVAL}:\nJeg tager\nden her.",
    ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}: Vent,\n{PLAYER}!\nLad os teste\nvores POKéMON!\nKom nu!\nJeg udfordrer\ndig!",
    ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}:\nOK, bedstefar!\nOverlad det\nroligt til mig!\n{PLAYER}, det\ngør mig ondt, men\njeg har ikke\nbrug for din\nhjælp!\nJeg har det! Jeg\nlåner en KORT\naf min søster!\nOg du skal ikke\nfå en, {PLAYER}!\nHahaha!",
    ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}: Mit\nPOKéMON ser\nmeget stærkere ud!",
    ["_OaksLabRivalReceivedMonText"] = "{RIVAL} modtager\n{RAM:wNameBuffer}!",
    ["_OaksLabRivalSmellYouLaterText"] = "{RIVAL}: OK!\nJeg vil træne\nmine POKéMON,\nså de bliver\nstærkere!\n{PLAYER}! Bedstefar!\nVi ses\nsenere!",
    ["_OaksLabRivalWhatAboutMeText"] = "{RIVAL}: Vent!\nBedstefar! Hvad\nmed mig?",
    ["_OaksLabRivalWhatDidYouCallMeForText"] = "{RIVAL}: Hvorfor\nbad du mig\nkomme herhen?",
