    ["_ParasDexEntry"] = "Denne POKéMON\nlever af\ntræernes rødder.\nSvampene på\nryggen bruger den\nsom værtsdyr.",
    ["_ParasectDexEntry"] = "Denne POKéMON\nbestår af en\nvært og en\nsnylter. Den\nforetrækker fugtige\nomgivelser.",
