    ["_PersianDexEntry"] = "Denne POKéMON\nhar meget smuk\npels. Det er\ndog et svært\nopdrageligt\nkæledyr.",
    ["_PewterCityCooltrainerFText"] = "Efter sigende\nskal CLEFAIRY\nstamme fra\nmånen!\nEfter\nMÅNESTENEN faldt\npå MÅNEBJERGET,\ndukkede de op\nfor første gang!",
    ["_PewterCityCooltrainerMText"] = "Her er der kun\nfå seriøse\nPOKéMON-trænere!\nMen BROCK,\nARENALEDEREN i\nPEWTER CITY,\nforstår sig på\nsit fag!",
    ["_PewterCityGymSignText"] = "PEWTER CITY\nPKMN-ARENA\nARENALEDER:\nBROCK\nDen stenhårde\nPOKéMON-træner!",
    ["_PewterCityMuseumSignText"] = "PEWTER CITY\nVIDENSKABS-\nMUSEUM",
    ["_PewterCityPokecenterGuyText"] = "Gab!\nAf JIGGLYPUFFS\nSANG bliver\nPOKéMON helt\ntrætte...\nMig også...\nSnorke...",
    ["_PewterCityPoliceNoticeSignText"] = "PAS PÅ!\nTyve har\nstjålet POKéMON-\nfossiler fra\nMÅNEBJERGET! Hvis\ndu har relevante\noplysninger,\nkontakt venligst\npolitiet i\nPEWTER CITY!",
    ["_PewterCitySignText"] = "PEWTER CITY.\nDen stengrå\nby!",
    ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "Har du allerede\nværet på MUSEET?",
    ["_PewterCitySuperNerd1ItsRightHereText"] = "Det er lige\nderovre! Man skal\nnok betale\nentré, men\ndet er det værd!",
    ["_PewterCitySuperNerd1WerentThoseFossilsAmazingText"] = "Var fossilerne\nfra MÅNEBJERGET\nikke enestående?",
    ["_PewterCitySuperNerd1YouHaveToGoText"] = "Virkelig ikke?\nDet er dog et\nbesøg værd!",
    ["_PewterCitySuperNerd2DoYouKnowWhatImDoingText"] = "Pst! Ved du,\nhvad jeg laver\nher?",
    ["_PewterCitySuperNerd2ImSprayingRepelText"] = "Jeg sprøjter\nSKJOLD, for\nat holde\nPOKéMON væk\nfra min have!",
    ["_PewterCitySuperNerd2ThatsRightText"] = "Rigtigt! Det er\nhårdt arbejde!",
    ["_PewterCityTrainerTipsText"] = "TIPS TIL TRÆNERE\nUanset varigheden\naf dets indsats\nfår hvert POKéMON\nerfaringspoint\nfor at deltage\ni en kamp,\\x30\nEP! ",
    ["_PewterCityYoungsterGoTakeOnBrockText"] = "Hvis du har nok\nmod, så prøv\ndig af med\nBROCK!",
    ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "Er du træner?\nBROCK leder\nkonstant efter\nnye\nudfordrere!\nFølg mig!",
    ["_PewterGymBrockBoulderBadgeInfoText"] = "\nDet er en\nofficiel ORDEN\nfra PKMN-LIGAEN!\nPOKéMON, der\ntilhører den, der\nbærer ORDENEN,\nbliver stærkere!\nFra nu af kan\ndine POKéMON\ntil enhver tid\nbruge BLITZ!",
    ["_PewterGymBrockPostBattleAdviceText"] = "Der findes de\nmest forskellige\ntrænere i\nverden!\nDu synes at\nvære en meget\ntalentfuld\nPOKéMON-TRÆNER!\nTag til\nPKMN-ARENAEN i\nCERULEAN CITY og\ntest dine\nevner der!",
    ["_PewterGymBrockPreBattleText"] = "Jeg er\nARENALEDEREN i\nPEWTER CITY,\nBROCK!\nMit motto er\net stenhårdt\nforsvar og\nklippefast\nbeslutsomhed!\nDerfor\ntræner jeg\nSTEN-POKéMON!\nVil du stadig\ntage kampen op\nmed mig? OK!\nVis mig, hvor\ngod du er!",
    ["_PewterGymBrockReceivedBoulderBadgeText"] = "Jeg har\nvurderet dig\nforkert!\nTag\nSTEN-ORDENEN som\ntegn på min\nrespekt!\n{PLAYER} modtager\nSTEN-ORDENEN!",
    ["_PewterGymBrockWaitTakeThisText"] = "Vent! Tag den\nher med!",
    ["_PewterGymCooltrainerMAfterBattleText"] = "Du er ganske god,\nmen ikke så\ngod som BROCK!",
    ["_PewterGymCooltrainerMBattleText"] = "Bliv, hvor du\ner, lille ven!\nDet tager\nstadig lysår,\nfør du kan\nmøde BROCK!",
    ["_PewterGymCooltrainerMEndBattleText"] = "Pokkers!\nLysår måler\nafstanden,\nikke tiden!",
    ["_PewterGymGuideAdviceText"] = "POKéMONen\nforrest på\nPOKéMON-LISTEN\nkæmper som\ndet første!\nHvis du ændrer\nrækkefølgen af\nPOKéMON'ene,\nkunne kampe\nblive lettere!",
    ["_PewterGymGuideBeginAdviceText"] = "Godt så! Så\nkan det gå løs!",
    ["_PewterGymGuideFreeServiceText"] = "Tippet er\ngratis! Lad\nos begynde!",
    ["_PewterGymGuidePostBattleText"] = "Lige som jeg\nhavde tænkt mig! \nDu kan blive en\nPOKéMON-CHAMPION!",
    ["_PewterGymGuidePreAdviceText"] = "Hej! Ser ud til,\nat du har\nstoffet til en\nPOKéMON-CHAMPION!\nJeg er ikke\ntræner, men jeg\nkan give dig\net par tips!\nLad mig vise\ndig vejen til\nsucces!",
    ["_PewterGymReceivedTM34Text"] = "{PLAYER} modtager\nTM34!",
    ["_PewterGymTM34NoRoomText"] = "Du har ikke\nplads lige nu til\nflere items!",
    ["_PewterMartSuperNerdText"] = "Hvis man\ntræner sine\nPOKéMON flittigt,\nkan selv svagere\nPOKéMON gøre\nsig godt for\noverraskelser!",
    ["_PewterMartYoungsterText"] = "En lyssky\ngammel mand\nsolgte mig denne\nmærkelige POKéMON!\nDet er helt\nsvagt og\nkostede ¥500!",
    ["_PewterNidoranHouseLittleBoyText"] = "NIDORAN, sid!",
    ["_PewterNidoranHouseMiddleAgedManText"] = "Vores POKéMON er\nen outsider,\nså det er\nsvært at\nopdrage!\nEn outsider\ner en POKéMON,\nman modtager ved\net bytte.\nDet udvikler\nsig hurtigt, men\ni kamp kan det\nforekomme, at\ndet ikke adlyder\nuerfarne\ntrænere!\nHvis vi bare\nhavde et par\nORDENER...",
    ["_PewterNidoranHouseNidoranText"] = "NIDORAN: Nidoran!",
    ["_PewterPokecenterGentlemanText"] = "Hvad!?\nTEAM ROCKET\nbefinder sig på\nMÅNEBJERGET?\nDet skal jeg\nstraks melde!\nForsvind!",
    ["_PewterPokecenterJigglypuffText"] = "JIGGLYPUFF: Puup\npupuu!",
    ["_PewterSpeechHouseGamblerText"] = "Med voksende\nerfaring lærer\nPOKéMON nye\nangreb!\nNogle angreb\nkan dog kun en\ntræner lære dem!",
    ["_PewterSpeechHouseYoungsterText"] = "POKéMON er\nlettere at\nfange, når de\ner skadet\neller sover!\nAlligevel er\nder ingen\ngaranti for\nsucces!",
    ["_PickUpPayDayMoneyText"] = "{PLAYER} samler\n¥{NUM:wTotalPayDayMoney, 3 | LEADING_ZEROES | LEFT_ALIGN} op!",
    ["_PidgeotDexEntry"] = "Denne POKéMON\nskyder ved\njagt lynhurtigt\nned under vandet\nfor at fange sit\nintetanende bytte.",
