    ["_PokemonFanClubBagFullText"] = "Du har ikke\nplads til flere\nitems!",
    ["_PokemonFanClubChairFinalText"] = "Hej, {PLAYER}!\nSkal jeg fortælle\ndig om mine\nPOKéMON?\nNej? Ærgerligt!",
    ["_PokemonFanClubChairmanIntroText"] = "Jeg er\nformanden for\nPOKéMON-FANKLUBBEN!\nJeg har fanget\nmere end\n100 POKéMON!\nJeg er meget\npertentlig, når\ndet handler om\nPOKéMON!\nAltså...\nEr du kommet\nhelt herud for\nat høre om mine\nPOKéMON?",
    ["_PokemonFanClubChairmanStoryText"] = "Fantastisk!\nSå hør her!\nDen, jeg holder\nmest af, er RAPIDASH!\nDet er... sødt...\nsmukt... klogt...\nog... spændende!\nEr du ikke\nenig? Det... er...\nmajestætisk...\nvenligt...\nJeg elsker det!\nNår... det...\nsover... varmt\nog hyggeligt...\nspektakulært...\nbetagende...\nUps! Hvor tiden\ndog går! Jeg\nholder dig op!\nTak, fordi du\nlyttede til mig!\nTag denne\ngave fra mig!",
    ["_PokemonFanClubExplainBikeVoucherText"] = "\nDu modtager en\nCYKEL for den!\nBekymr dig ikke\nom mig, jeg kan\nFLYVE med min\nFEAROW!\nJeg har altså\nikke brug for en\nCYKEL!\nJeg håber, du\ncykler med glæde!",
    ["_PokemonFanClubNoStoryText"] = "Åh. Kom forbi\nigen, når jeg\nskal fortælle\ndig noget!",
