    ["_Rival1WinText"] = "{RIVAL}: Ja! Jeg\ner den bedste!",
    ["_RivalDefeatedText"] = "NEJ!\nDet kan ikke\nvære sandt! Mine\nbedste POKéMON\ner slået!\nEr min sejrsgang\nallerede forbi?\nEfter al den\nanstrengelse for\nat blive LIGA-\nCHAMPION?\nDet er ikke\nfair!",
    ["_RivalVictoryText"] = "Haha! Jeg\nhar VUNDET!\nJeg er simpelthen \nfor god til dig, \n{PLAYER}!\nTrods alt er du\nkommet hertil! Jeg\nhavde dog\nforventet mere\naf dig,\n{RIVAL}!\nMåske næste\ngang, din\nkæmper! Hahaha!",
    ["_RockTunnel1FCooltrainerF1AfterBattleText"] = "Jeg har set en\nMACHOKE her i\ntunnelen!",
    ["_RockTunnel1FCooltrainerF1BattleText"] = "Hovsa! Kom ikke\nfor tæt på mig\ni mørket!",
    ["_RockTunnel1FCooltrainerF1EndBattleText"] = "Det\nvar for mørkt!",
    ["_RockTunnel1FCooltrainerF2AfterBattleText"] = "Og du så dog så\nsød og uskyldig\nud!",
    ["_RockTunnel1FCooltrainerF2BattleText"] = "Jeg er kommet\nherhen på grund\naf POKéMON!",
    ["_RockTunnel1FCooltrainerF2EndBattleText"] = "\nAlle mine\nPOKéMON blev\nbesejret!",
    ["_RockTunnel1FCooltrainerF3AfterBattleText"] = "Puh! Jeg er helt\nvåd af sved!",
    ["_RockTunnel1FCooltrainerF3BattleText"] = "Du har\nPOKéMON!\nLad os kæmpe!",
    ["_RockTunnel1FCooltrainerF3EndBattleText"] = "\nDu er en\nhård nød!",
    ["_RockTunnel1FHiker1AfterBattleText"] = "Pas på med\nONIX! Den\nklemmer dig som\nen citron!",
    ["_RockTunnel1FHiker1BattleText"] = "Denne tunnel er\nforbandet lang!",
    ["_RockTunnel1FHiker1EndBattleText"] = "Nå! Du\nhar vundet!",
    ["_RockTunnel1FHiker2AfterBattleText"] = "Jeg må gøre\ndenne omvej kun\npå grund af det\nsovende POKéMON\npå Rute 12.",
    ["_RockTunnel1FHiker2BattleText"] = "Kunne det være,\nat jeg er faret\nvild?",
    ["_RockTunnel1FHiker2EndBattleText"] = "Roligt!\nHvor er jeg?\nHvor kommer man\nud herfra?",
    ["_RockTunnel1FHiker3AfterBattleText"] = "Du har talent!\nDu kan ikke\nvære en amatør!",
    ["_RockTunnel1FHiker3BattleText"] = "En amatør\nsom dig burde\nvise lidt mere\nrespekt!",
    ["_RockTunnel1FHiker3EndBattleText"] = "\nJeg giver op!",
    ["_RockTunnel1FSignText"] = "KLIPPETUNNEL\nCERULEAN CITY -\nLAVENDER TOWN",
    ["_RockTunnel1FSuperNerdAfterBattleText"] = "Undervejs fanger\njeg mig en\nZUBAT!",
    ["_RockTunnel1FSuperNerdBattleText"] = "Mine POKéMON\nvil kæmpe!\nSå går det løs!",
    ["_RockTunnel1FSuperNerdEndBattleText"] = "\nGAME OVER!",
    ["_RockTunnelB1FCooltrainerF1AfterBattleText"] = "Jeg vil hjem!",
    ["_RockTunnelB1FCooltrainerF1BattleText"] = "Vandrere bruger\ngrene til at\nmarkere deres\nvej.",
    ["_RockTunnelB1FCooltrainerF1EndBattleText"] = "\nJeg gjorde mit\nbedste!",
    ["_RockTunnelB1FCooltrainerF2AfterBattleText"] = "Jeg kan kun lide\nsmå POKéMON,\nde store gør\nmig bange!",
    ["_RockTunnelB1FCooltrainerF2BattleText"] = "Jeg kommer ikke\nofte herhen. Men\njeg vil kæmpe!",
    ["_RockTunnelB1FCooltrainerF2EndBattleText"] = "Åh!\nJeg har tabt!",
    ["_RockTunnelB1FHiker1AfterBattleText"] = "Jeg træner\nhellere mine\nmuskler end\nmin hjerne!!!",
    ["_RockTunnelB1FHiker1BattleText"] = "Haha! Kan du\nbesejre mig?",
    ["_RockTunnelB1FHiker1EndBattleText"] = "Hovsa!\nDet var for\nmeget af det gode!",
    ["_RockTunnelB1FHiker2AfterBattleText"] = "I bjergene\nfinder man mange\nSTEN-POKéMON.",
    ["_RockTunnelB1FHiker2BattleText"] = "Mit POKéMON\nvil lære dig\nat frygte!",
    ["_RockTunnelB1FHiker2EndBattleText"] = "Jeg\ngiver op! Du\ner bedre!",
    ["_RockTunnelB1FHiker3AfterBattleText"] = "Jeg vil træne\nmed mine POKéMON!",
    ["_RockTunnelB1FHiker3BattleText"] = "Vis mig, hvad du\nkan!",
    ["_RockTunnelB1FHiker3EndBattleText"] = "Du\ner god!",
    ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "Giver du mig\nPOKéDEXEN, når\nden er færdig?",
    ["_RockTunnelB1FSuperNerd1BattleText"] = "Har du en\nPOKéDEX? Sejt!\nJeg vil også\ngerne have en!",
    ["_RockTunnelB1FSuperNerd1EndBattleText"] = "Åh,\njeg er så\nmisundelig!!!",
    ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "Sjove typer\nklæder sig gerne\nud som POKéMON.",
    ["_RockTunnelB1FSuperNerd2BattleText"] = "Vil du høre\nnoget om sjove\ntyper?",
    ["_RockTunnelB1FSuperNerd2EndBattleText"] = "\nSå langt, så godt.",
    ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "Jeg elsker\nkunsten,\nikke kampen!",
    ["_RockTunnelB1FSuperNerd3BattleText"] = "Derhjemme tegner\njeg gerne POKéMON.",
    ["_RockTunnelB1FSuperNerd3EndBattleText"] = "Jeg\ner udmattet!",
    ["_RockTunnelPokecenterFisherText"] = "Jeg fik\n5000¥ for en\nubrugelig\nGULDKLUMP!",
    ["_RockTunnelPokecenterGentlemanText"] = "Deres element gør\nnogle POKéMON\nstærkere eller\nsvagere over for\nandre!",
    ["_RockTunnelPokecenterGuyText"] = "Jeg har hørt,\nat der spøger\nonde SPØGELSER\ni LAVENDER TOWN!",
    ["_RocketHide3AfterBattleText3"] = "Gå bare videre!\nDu skal bruge\nLIFTÅBNEREN, og\nden mangler du!",
    ["_RocketHideout3BattleText"] = "Vi havde allerede\nhørt, at du var\npå vej!",
    ["_RocketHideout3EndBattleText3"] = "Hvad? Har\njeg tabt? Ah!",
    ["_RocketHideoutB1FRocket1AfterBattleText"] = "Vil du lægge dig\nud med TEAM\nROCKET?",
    ["_RocketHideoutB1FRocket1BattleText"] = "Hvordan er du\nkommet herhen, lille ven?",
    ["_RocketHideoutB1FRocket1EndBattleText"] = "Av!\nSlået!",
    ["_RocketHideoutB1FRocket2AfterBattleText"] = "Vores hævn\nbliver grufuld,\ndin lømmel!",
    ["_RocketHideoutB1FRocket2BattleText"] = "Du har mod til\nat trænge ind her!",
    ["_RocketHideoutB1FRocket2EndBattleText"] = "\nPokkers! Fejlet!",
    ["_RocketHideoutB1FRocket3AfterBattleText"] = "SILPH SCOPE?\nJeg ved ikke,\nhvad du taler om!",
    ["_RocketHideoutB1FRocket3BattleText"] = "Alarm!\nIndtrængere!",
    ["_RocketHideoutB1FRocket3EndBattleText"] = "Jeg\nkunne ikke stoppe\nham!!!",
    ["_RocketHideoutB1FRocket4AfterBattleText"] = "OK, OK, jeg\nsladrer! Brug\nelevatoren til\nCHEFEN!",
    ["_RocketHideoutB1FRocket4BattleText"] = "Hvad vil du\noverhovedet her?",
    ["_RocketHideoutB1FRocket4EndBattleText"] = "\nDet kan ikke\nfungere!",
    ["_RocketHideoutB1FRocket5AfterBattleText"] = "Ups, døren er\ngået op!",
    ["_RocketHideoutB1FRocket5BattleText"] = "Hvad har du\nmistet her?",
    ["_RocketHideoutB1FRocket5EndBattleText"] = "\nHvad skete der?",
    ["_RocketHideoutB2FRocketAfterBattleText"] = "TEAM ROCKETS\nhovedkvarter har\n4 kældre-\netager. Du finder\naldrig CHEFEN!!!",
    ["_RocketHideoutB2FRocketBattleText"] = "CHEFEN siger,\nat SILPH SCOPE\ngør spøgelser\nsynlige!",
    ["_RocketHideoutB2FRocketEndBattleText"] = "STOP!\nJeg overgiver mig!",
    ["_RocketHideoutB3FRocket1AfterBattleText"] = "SILPH SCOPE?\nApparatet, som\nCHEFEN har\nstjålet? Det er\nher et sted...",
    ["_RocketHideoutB3FRocket1BattleText"] = "Bland dig uden\nom TEAM ROCKETS\nanliggender!",
    ["_RocketHideoutB3FRocket1EndBattleText"] = "Puha! Jeg\ner slået!",
    ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "Tydeligvis\ntræner du dine\nPOKéMON meget\nomhyggeligt!\nAlligevel ville\ndu aldrig\nforstå mine mål\nog motiver...\nDenne gang lader\njeg dig endnu\nslippe af sted...\nMen vi ses\nigen!",
    ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "Jeg er dybt\nimponeret. Du\ner faktisk\nnået langt!",
    ["_RocketHideoutB4FGiovanniWhatCannotBeText"] = "NEJ!\nJeg har fejlet\nynkeligt!",
    ["_RocketHideoutB4FRocket1AfterBattleText"] = "Vil du ødelægge\nTEAM ROCKET?",
    ["_RocketHideoutB4FRocket1BattleText"] = "Det var dig, der\nødelagde vores\nplaner på\nMÅNEBJERGET!",
    ["_RocketHideoutB4FRocket1EndBattleText"] = "Denne\ndreng er simpelthen\nuslåelig!!!",
    ["_RocketHideoutB4FRocket2AfterBattleText"] = "Nåde, CHEF! Jeg\nhar fejlet...",
    ["_RocketHideoutB4FRocket2BattleText"] = "Mærker du ikke\nskønheden ved\nden mørke side\naf magten?",
    ["_RocketHideoutB4FRocket2EndBattleText"] = "Av!",
    ["_RocketHideoutB4FRocket3AfterBattleText"] = "Pokkers! Jeg har\nmistet\nLIFTÅBNEREN!",
    ["_RocketHideoutB4FRocket3BattleText"] = "Jeg vil aldrig\ngive dig\nLIFTÅBNEREN!",
    ["_RocketHideoutB4FRocket3EndBattleText"] = "Åh nej!",
    ["_RocketHideoutElevatorAppearsToNeedKeyText"] = "Hmm, her har\nman brug for en\nnøgle!",
    ["_RoseText"] = " øges!",
    ["_Route10CooltrainerF1AfterBattleText"] = "Jeg har set nogle\nPOKéMANIAKER\ni dette område.",
    ["_Route10CooltrainerF1BattleText"] = "Hver gang jeg\nhar kæmpet i\nen PKMN-ARENA, \ner jeg blevet\nbesejret!",
    ["_Route10CooltrainerF1EndBattleText"] = "\nNej! Ikke\nigen!",
    ["_Route10CooltrainerF2AfterBattleText"] = "Mange POKéMON\ni dette område\ner grove!\nJeg ville ønske,\net var lyserødt\nog havde et\nblomstermønster!",
    ["_Route10CooltrainerF2BattleText"] = "Jeg føler mig\nudmattet af\nal vandringen...",
    ["_Route10CooltrainerF2EndBattleText"] = "Jeg\ner ikke i form!",
    ["_Route10Hiker1AfterBattleText"] = "Snøft...\nDenne forbandede\nforkølelse!",
    ["_Route10Hiker1BattleText"] = "Ha-ha-ha-ha!",
    ["_Route10Hiker1EndBattleText"] = "Ha-ha!\nHaha-ha-tji!",
    ["_Route10Hiker2AfterBattleText"] = "Jeg har fået\nnok af bjergluft!",
    ["_Route10Hiker2BattleText"] = "Ahh! Bjergluften\ner så vidunderlig\nforfriskende!",
    ["_Route10Hiker2EndBattleText"] = "Jeg\nkan tænke klart\nigen!",
    ["_Route10PowerPlantSignText"] = "KRAFTVÆRK",
    ["_Route10RockTunnelSignText"] = "KLIPPETUNNEL",
    ["_Route10SuperNerd1AfterBattleText"] = "Derhjemme har\njeg endnu flere\nsjældne POKéMON!",
    ["_Route10SuperNerd1BattleText"] = "Er du også en\nPOKéMANIAK?\nVil du se min\nsamling?",
    ["_Route10SuperNerd1EndBattleText"] = "Nå,\ndet gør ikke noget!",
    ["_Route10SuperNerd2AfterBattleText"] = "Jeg fortryder,\nat du besejrede\nmig!",
    ["_Route10SuperNerd2BattleText"] = "Hej dig, vil du\nse mine POKéMON?",
    ["_Route10SuperNerd2EndBattleText"] = "Nej!\nMine POKéMON!",
    ["_Route11DiglettsCaveSignText"] = "DIGLETTS HULE",
    ["_Route11Gambler1AfterBattleText"] = "Hele\nlivet er et\nhasardspil!",
    ["_Route11Gambler1BattleText"] = "Prøv din\nlykke mod mig!",
    ["_Route11Gambler1EndBattleText"] = "\nLykken har\nforladt mig!",
    ["_Route11Gambler2AfterBattleText"] = "Kujoner har\ningen chance i\nPOKéMONs\nverden!",
    ["_Route11Gambler2BattleText"] = "Konkurrencer! Jeg\nkan ikke modstå\ndem!",
    ["_Route11Gambler2EndBattleText"] = "I det mindste\nhavde jeg en\nchance!",
    ["_Route11Gambler3AfterBattleText"] = "Det var ren\ntilfældighed! Kun\nheld!",
    ["_Route11Gambler3BattleText"] = "Haha! Jeg har\naldrig\ntabt endnu!",
