    ["_Route11Gate2FLeftBinocularsSnorlaxText"] = "Du kigger gennem\nkikkerten.\nMidt på vejen\nsover en\nstor POKéMON!",
    ["_Route11Gate2FOaksAideItemfinderDescriptionText"] = "På jorden\nligger der ofte\nitems, man ikke\nkan se.\nDETEKTOREN\nopsporer items i\nnærheden af dig!\nDen viser dog\nikke den\nnøjagtige position!\nDu skal se\ndig godt omkring!",
    ["_Route11Gate2FRightBinocularsText"] = "Du kigger gennem\nkikkerten.\nDen eneste vej\nfra CERULEAN CITY\ntil LAVENDER TOWN\ngår gennem\nKLIPPETUNNELEN.",
    ["_Route11SuperNerd1AfterBattleText"] = "Skån\nmiljøet og spar\nenergi!",
    ["_Route11SuperNerd1BattleText"] = "Pas på!\nJeg lægger lige\nkabler her!",
    ["_Route11SuperNerd1EndBattleText"] = "\nDet var et\nelektrisk stød!",
    ["_Route11SuperNerd2AfterBattleText"] = "Jeg må hellere\ngå tilbage til\narbejdet.",
    ["_Route11SuperNerd2BattleText"] = "Pas på med\nhøjspænding!",
    ["_Route11SuperNerd2EndBattleText"] = "Av!\nGnisten sprang\nover!",
    ["_Route11Youngster1AfterBattleText"] = "I det mindste\nprøvede jeg!\nJeg skammer\nmig ikke!",
    ["_Route11Youngster1BattleText"] = "Har du lyst til\nat kæmpe mod\nmig?",
    ["_Route11Youngster1EndBattleText"] = "Hvad?\nDet er ondt!",
    ["_Route11Youngster2AfterBattleText5"] = "Hvad vil du\nmere? Lad mig\nendelig være alene!",
    ["_Route11Youngster2BattleText"] = "Jeg er lige\nbegyndt at\ntræne POKéMON!",
    ["_Route11Youngster2EndBattleText"] = "Pokkers!\nJeg hader\nsvage POKéMON!",
    ["_Route11Youngster3AfterBattleText"] = "Fra bjergene\nstiger nogle gange\net tykt\nPOKéMON ned.\nDet er meget\nstærkt! Prøv at\nfange det!",
    ["_Route11Youngster3BattleText"] = "I min klasse\ner jeg den\nbedste!",
    ["_Route11Youngster3EndBattleText"] = "Jeg må\ntræne mine POKéMON\nmere!",
    ["_Route11Youngster4AfterBattleText"] = "Jeg må fange\net par stærkere!",
    ["_Route11Youngster4BattleText"] = "Mine POKéMON\nburde være\nklar!",
    ["_Route11Youngster4EndBattleText"] = "Det\nvar svagt!",
    ["_Route12CooltrainerMAfterBattleText"] = "Hvis jeg havde\nen MÅNESTEN,\nkunne mine\nPOKéMON\nudvikle sig videre!",
    ["_Route12CooltrainerMBattleText"] = "Har du en\nMÅNESTEN?",
    ["_Route12CooltrainerMEndBattleText"] = "Av!",
    ["_Route12Fisher1AfterBattleText"] = "En dag vil jeg\ngøre det store\nfangst!",
    ["_Route12Fisher1BattleText"] = "Cool! Der er\nnoget gået i\nnettet!",
    ["_Route12Fisher1EndBattleText"] = "Pokkers!\nBare en lille\nfisk!",
    ["_Route12Fisher2AfterBattleText"] = "Havde jeg en\nbedre fiskestang,\nville jeg fange\nbedre POKéMON!",
    ["_Route12Fisher2BattleText"] = "Bare rolig!\nSom fisker skal\nman være\ntålmodig!",
    ["_Route12Fisher2EndBattleText"] = "Den\nslap væk fra mig!",
    ["_Route12Fisher3AfterBattleText"] = "Du forstår dig\nvirkelig meget\npå POKéMON, men\njeg er den\nbedre fisker!",
    ["_Route12Fisher3BattleText"] = "FISKEKONGEN\nmod\nPOKéMON-BARNET!",
    ["_Route12Fisher3EndBattleText"] = "Det var\ntop!",
    ["_Route12Fisher4AfterBattleText"] = "OK, med tiden\nvænner man sig\ntil at\ntabe!",
    ["_Route12Fisher4BattleText"] = "Egentlig ville\njeg hellere\narbejde...",
    ["_Route12Fisher4EndBattleText"] = "Det var\nsandelig ikke\nnogen leg!",
    ["_Route12Fisher5AfterBattleText"] = "Jeg fanger altid\nMAGIKARP. Men\nde er så\nsvage!",
    ["_Route12Fisher5BattleText"] = "Man ved aldrig,\nhvad det næste\nfangst bliver!",
    ["_Route12Fisher5EndBattleText"] = "Jeg\nhar tabt!",
    ["_Route12Gate1FGuardText"] = "Ovenfor\ntrappen er der\net udkigspunkt!",
    ["_Route12Gate2FBrunetteGirlReceivedTM39Text"] = "{PLAYER} modtager\nTM39!",
    ["_Route12Gate2FBrunetteGirlTM39ExplanationText"] = "TM39 er\nSTJERNESKUD.\nSTJERNESKUD er\nen sikker\nteknik, der kan\nvære til stor\nnytte i vigtige\nkampe!",
    ["_Route12Gate2FBrunetteGirlTM39NoRoomText"] = "Åh, du kan ikke\nbære den lige\nnu.",
    ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "Mine POKéMON\nblev lagt til\nhvile i\nPOKéMON-TÅRNET.\nJeg giver dig\ndenne TM. Jeg\nhar ikke længere\nbrug for den...",
    ["_Route12Gate2FLeftBinocularsText"] = "Du kigger gennem\nkikkerten.\nDu ser en\nfiskende mand!",
    ["_Route12Gate2FRightBinocularsText"] = "Du kigger gennem\nkikkerten.\nDu ser\nPOKéMON-TÅRNET!",
    ["_Route12SignText"] = "RUTE 12, NORD:\nLAVENDER TOWN.",
    ["_Route12SnorlaxCalmedDownText"] = "SNORLAX har\nroet sig igen!\nDet gaber og\ngår tilbage\ntil bjergene!",
    ["_Route12SnorlaxText"] = "En sovende\nPOKéMON\nspærrer\nvejen!",
    ["_Route12SnorlaxWokeUpText"] = "SNORLAX er\nvågnet!\nDet er surt\nog angriber\nsøvnigt!",
    ["_Route12SportFishingSignText"] = "SPORTSFISKE-ZONE",
    ["_Route12SuperNerdAfterBattleText"] = "Vand leder\nelektricitet.\nAngrib VAND-\nPOKéMON med\nelektricitet!",
    ["_Route12SuperNerdBattleText"] = "Elektricitet er\nmin styrke!",
    ["_Route12SuperNerdEndBattleText"] = "\nStrømkredsen\nafbrudt!",
    ["_Route12SuperRodHouseFishingGuruDoYouLikeToFishText"] = "Min bror er\nPROFFISKEREN!\nJeg elsker\nlystfiskeri!\nVil du også\ngerne fiske?",
    ["_Route12SuperRodHouseFishingGuruFishingWayOfLifeText"] = "\nAt fiske er ikke\nkun en sport, det\ner en kunst!\nSå drag af sted\nfor at gøre det\nstore fangst!",
    ["_Route12SuperRodHouseFishingGuruNoRoomText"] = "Åh nej!\nJeg har en\ngave til\ndig! Men du\nkan ikke bære\nmere!",
    ["_Route12SuperRodHouseFishingGuruReceivedSuperRodText"] = "Sejt! Jeg kan\nrigtig lide dig!\nTag den her og\nnyd\nfiskerlivet!\n{PLAYER} modtager\nen {RAM:wStringBuffer}!",
