    ["_Route1Youngster1AlsoGotPokeballsText"] = "Vil du fange\nPOKéMON? Vi har\nogså POKéBALLE\ni sortimentet!",
    ["_Route1Youngster1GotPotionText"] = "{PLAYER} modtager\n{RAM:wStringBuffer}!",
    ["_Route1Youngster1MartSampleText"] = "Hej! Jeg arbejder\ni et\nPKMN-SUPERMARKED.\nVi sælger\nmange praktiske\nting! Du finder\nvores butik i\nVIRIDIAN CITY.\nBedst giver jeg\ndig en\nreklamegave!\nHer, værsgo!",
    ["_Route1Youngster1NoRoomText"] = "Du kan ikke\nbære flere\nitems!",
    ["_Route1Youngster2Text"] = "Ser du\ntrinene her?\nDu kan ikke\nklatre op,\nmen til gengæld\nkan du hoppe ned!\nSådan kommer du\nmeget hurtigere\ntilbage til\nPALLET TOWN.",
    ["_Route20CooltrainerMAfterBattleText"] = "Kan jeg med\nmine FUGLE-\nPOKéMON stadig\nflyve tilbage?",
    ["_Route20CooltrainerMBattleText"] = "Mit\nFUGLE-POKéMON\nhar båret mig\nherhen!",
    ["_Route20CooltrainerMEndBattleText"] = "\nÅh nej!",
    ["_Route20SeafoamIslandsSignText"] = "SKUMØERNE",
    ["_Route20Swimmer1AfterBattleText"] = "Jeg ville ønske,\njeg kunne ride\npå en POKéMON.",
    ["_Route20Swimmer1BattleText"] = "Vandet er\nmeget lavt her.",
    ["_Route20Swimmer1EndBattleText"] = "\nPlask!",
    ["_Route20Swimmer2AfterBattleText"] = "Under denne\nø findes der\nen kæmpe hule!",
    ["_Route20Swimmer2BattleText"] = "SKUMØERNE\ner et stille\ntilflugtssted!",
    ["_Route20Swimmer2EndBattleText"] = "\nSlut med det!",
    ["_Route20Swimmer3AfterBattleText"] = "Vil du holde\nmig med\nselskab?",
    ["_Route20Swimmer3BattleText"] = "Jeg lader mig\ngerne drive med\nfiskene!",
    ["_Route20Swimmer3EndBattleText"] = "Av!",
    ["_Route20Swimmer4AfterBattleText"] = "SKUMØERNE\nvar engang ÉN\nstor ø!",
    ["_Route20Swimmer4BattleText"] = "Holder du også\nferie lige nu?",
    ["_Route20Swimmer4EndBattleText"] = "Du\nkender ingen\nnåde!",
    ["_Route20Swimmer5AfterBattleText"] = "Jeg skulle have\ntrænet mine\nPOKéMON, ikke\nmin krop!",
    ["_Route20Swimmer5BattleText"] = "Se roligt på\nmin veltrænede\nkrop!",
    ["_Route20Swimmer5EndBattleText"] = "\nVaskeklud!",
    ["_Route20Swimmer6AfterBattleText"] = "Det ville nok\nvære sjovt at\nride på en\nPOKéMON!",
    ["_Route20Swimmer6BattleText"] = "Hvorfor rider du\npå POKéMONen?\nKan du ikke\nsvømme?",
    ["_Route20Swimmer6EndBattleText"] = "Jeg\nblev torpederet!",
    ["_Route20Swimmer7AfterBattleText"] = "Mon min perle\nville blive\nstørre i en\nCLOYSTER?",
    ["_Route20Swimmer7BattleText"] = "Min ven gav\nmig en stor\nperle!",
    ["_Route20Swimmer7EndBattleText"] = "\nHold fingrene\nvæk fra min perle!",
    ["_Route20Swimmer8AfterBattleText"] = "På\nCINNOBER-ØEN\nhar POKéMON\nbosat sig i en\nforladt villa!",
    ["_Route20Swimmer8BattleText"] = "Jeg er svømmet\nherover fra\nCINNOBER-ØEN!",
    ["_Route20Swimmer8EndBattleText"] = "Jeg\ner skuffet!",
    ["_Route20Swimmer9AfterBattleText"] = "CINNOBER-ØEN\ner en vulkansk\nø!",
    ["_Route20Swimmer9BattleText"] = "På\nCINNOBER-ØEN\nfindes et\nPOKéMON-LABORATORIUM.",
    ["_Route20Swimmer9EndBattleText"] = "Vent!",
    ["_Route21Fisher1AfterBattleText"] = "Hidtil har jeg\nendnu ikke\nfanget noget!",
    ["_Route21Fisher1BattleText"] = "Vil du gerne\nvide, om fiskene\nbider?",
    ["_Route21Fisher1EndBattleText"] = "Pokkers!",
    ["_Route21Fisher2AfterBattleText"] = "Åh nej! Jeg har\nallerede igen \nfanget en\nMAGIKARP!",
    ["_Route21Fisher2BattleText"] = "Jeg har gjort\net godt fangst!\nVil du\nse det?",
    ["_Route21Fisher2EndBattleText"] = "NEJ!\nMAGIKARP!",
    ["_Route21Fisher3AfterBattleText"] = "Jeg var bare\nsur, fordi jeg\nendnu ikke havde\nfanget noget.",
    ["_Route21Fisher3BattleText"] = "Hey, du skræmmer\nfiskene væk!",
    ["_Route21Fisher3EndBattleText"] = "\nUndskyld,\njeg ville ikke\nvære så barsk!",
    ["_Route21Fisher4AfterBattleText"] = "Juhu! Noget\nhar bidt på!",
    ["_Route21Fisher4BattleText"] = "Hold mig med\nselskab, indtil\nnoget bider!",
    ["_Route21Fisher4EndBattleText"] = "Nå,\ni det mindste\ngik der noget\ntid!",
    ["_Route21Swimmer1AfterBattleText"] = "Men jeg kan\nogså godt lide\nbjergene!",
    ["_Route21Swimmer1BattleText"] = "Havet renser\nkrop og sjæl!",
    ["_Route21Swimmer1EndBattleText"] = "Nej!",
    ["_Route21Swimmer2AfterBattleText"] = "Hvordan så jeg\nud? Som en våd\nsæk? Skrid\nendelig!",
    ["_Route21Swimmer2BattleText"] = "Generer det dig,\nat jeg svømmer\nher?",
    ["_Route21Swimmer2EndBattleText"] = "Det\nvar under\nbæltestedet!",
    ["_Route21Swimmer3AfterBattleText"] = "Hvor har du\nfanget dine\nPOKéMON?",
    ["_Route21Swimmer3BattleText"] = "Jeg har fanget\nalle mine POKéMON\npå havet!",
    ["_Route21Swimmer3EndBattleText"] = "\nAuweia! Jeg er\ngået ned!",
    ["_Route21Swimmer4AfterBattleText"] = "Du har vundet!\nMen jeg kan\nstadig vinde\nmaraton og\ncykelløbet!",
    ["_Route21Swimmer4BattleText"] = "Jeg deltager i\nen triatlon!",
    ["_Route21Swimmer4EndBattleText"] = "Puha,\nflæser...",
    ["_Route21Swimmer5AfterBattleText"] = "Solen har ristet\nmig som en\nkylling!",
    ["_Route21Swimmer5BattleText"] = "Ahh!\nNyd solen og\nvinden!",
    ["_Route21Swimmer5EndBattleText"] = "Ups!\nJeg har tabt!",
    ["_Route22GateGuardGoRightAheadText"] = "Åh! Du bærer\nSTEN-ORDENEN!\nSå må du\ngå videre!",
    ["_Route22GateGuardICantLetYouPassText"] = "\nOrdre er\nordre! Jeg\nmå ikke lade\ndig passere!",
    ["_Route22GateGuardNoBoulderbadgeText"] = "Kun erfarne\ntrænere må\npassere her!\nOg du har\nikke STEN-ORDENEN\nendnu!",
    ["_Route22PokemonLeagueSignText"] = "PKMN-LIGA\nHovedindgang",
    ["_Route22Rival1DefeatedText"] = "Åh nej!\nSå meget held som\ndig kan man ikke\nhave!",
    ["_Route22Rival1VictoryText"] = "{RIVAL}: Hvad?\nHvorfor jeg har\nto POKéMON?\nDumt spørgsmål!\nFang hellere\nselv et par\ntil!",
    ["_Route22Rival2DefeatedText"] = "Hvad!?\nJeg var for\nubetænksom!",
    ["_Route22Rival2VictoryText"] = "{RIVAL}: Hahaha!\n{PLAYER}! Var det\nvirkelig alt? Du\ner ikke i nærheden\naf så god som\nmig, makker!\nTræn hellere\nlidt mere,\ndin taber!",
    ["_Route22RivalAfterBattleText1"] = "I PKMN-LIGAEN\nfindes der mange\nstærke trænere!\nJeg må finde en\nvej forbi\ndem.\nDu burde\nholde op med at\ndrive rundt og\nkomme i\ngang!",
    ["_Route22RivalAfterBattleText2"] = "Det var en god\nopvarmningstræning!\nJeg er godt\nforberedt til\nPKMN-LIGAEN!\n{PLAYER}, selv\nom du har\nvundet, skal du\ntræne mere!\nJeg tror, du\ner klar over\ndet! Vi ses!",
    ["_Route22RivalBeforeBattleText1"] = "{RIVAL}: Hey!\n{PLAYER}!\nEr du på\nvej til\nPKMN-LIGAEN?\nGlem det!\nDu har\nsandsynligvis\nikke engang\nen ORDEN!\nVagten vil slet\nikke lade\ndig komme igennem!\nNå, er dine\nPOKéMON\negentlig\nblevet stærkere?",
    ["_Route22RivalBeforeBattleText2"] = "{RIVAL}: Hvad?!\n{PLAYER}!\nSikke en\noverraskelse!\nSå du er også\npå vej til\nPKMN-LIGAEN, ikke?\nHar du også alle\nORDENERNE?\nDet er sejt!\n{PLAYER}, jeg\nvil varme op\ntil PKMN-LIGAEN\nved at besejre\ndig!\nSå, kom så!",
    ["_Route23GoRightAheadText"] = "\nOK, fortsæt\ndin vej!",
    ["_Route23OhThatIsTheBadgeText"] = "Du må kun\npassere, hvis\ndu allerede har\n{RAM:wNameBuffer}!\nVidunderligt!\nDu bærer\n{RAM:wNameBuffer}!",
    ["_Route23VictoryRoadGateSignText"] = "SEJRSVEJEN\n- PKMN-LIGA",
    ["_Route23YouDontHaveTheBadgeYetText"] = "Du må kun\npassere med\n{RAM:wNameBuffer}!\nDu har ikke\n{RAM:wNameBuffer} endnu!\nKun den, der\nbærer den, må\nkomme ind i\nPKMN-LIGAEN!",
    ["_Route24CooltrainerF1AfterBattleText"] = "Jeg gav alt, jeg\nskammer mig\nikke!",
    ["_Route24CooltrainerF1BattleText"] = "Jeg er nr. 4!\nBliver du træt?",
    ["_Route24CooltrainerF1EndBattleText"] = "Jeg har\nogså tabt!",
    ["_Route24CooltrainerF2AfterBattleText"] = "Jeg gav alt, jeg\nskammer mig\nikke!",
    ["_Route24CooltrainerF2BattleText"] = "Jeg er nr. 2!\nNu bliver det\nalvor!",
    ["_Route24CooltrainerF2EndBattleText"] = "Hvordan\nkunne jeg tabe?",
    ["_Route24CooltrainerM1DefeatedText"] = "Arrgh!\nDu er god!",
    ["_Route24CooltrainerM1JoinTeamRocketText"] = "Vil du også\nblive medlem af\nTEAM ROCKET?\nVores\ngruppering\nbruger POKéMON\ntil djævelske\nformål!\nVil du melde\ndig ind?\nVirkelig ikke?\nKom nu,\nbliv medlem!\nJeg anbefaler\ndig at blive\nmedlem!\nJeg tror, jeg\nmå lave lidt\novertalelses-\narbejde!\nDette tilbud\nkan du ikke\nafvise!",
    ["_Route24CooltrainerM1NoRoomText"] = "Du har ikke\nplads til flere\nitems!",
    ["_Route24CooltrainerM1ReceivedNuggetText"] = "{PLAYER} modtager\nen {RAM:wStringBuffer}!",
    ["_Route24CooltrainerM1YouBeatOurContestText"] = "Hjertelig\ntillykke!\nDu har besejret\nalle fem trænere!",
    ["_Route24CooltrainerM1YouCouldBecomeATopLeaderText"] = "Med dine evner\nville du let\nblive CHEFENS\nhøjre hånd i\nTEAM ROCKET!",
    ["_Route24CooltrainerM1YouJustEarnedAPrizeText"] = "\nDu har vundet\nen fantastisk\npræmie!",
    ["_Route24CooltrainerM2AfterBattleText"] = "Jeg gemte mig,\nfordi folkene på\nbroen gjorde mig\nbange!",
    ["_Route24CooltrainerM2BattleText"] = "Jeg observerede\ndin optræden fra\ngræsset!",
    ["_Route24CooltrainerM2EndBattleText"] = "Jeg\nså vel alligevel\nikke noget!",
    ["_Route24CooltrainerM3AfterBattleText"] = "Jeg gav alt, jeg\nskammer mig\nikke!",
    ["_Route24CooltrainerM3BattleText"] = "Jeg er nr. 5!\nJeg mader dig!",
    ["_Route24CooltrainerM3EndBattleText"] = "Det\nvar for meget af\ndet gode!",
    ["_Route24Youngster1AfterBattleText"] = "Jeg gav alt, jeg\nskammer mig\nikke!",
    ["_Route24Youngster1BattleText"] = "Her kommer nr. 3!\nJeg gør livet\nsvært for dig!",
    ["_Route24Youngster1EndBattleText"] = "Ah!\nTaget på sengen!",
    ["_Route24Youngster2AfterBattleText"] = "Jeg gav alt, jeg\nskammer mig\nikke!",
    ["_Route24Youngster2BattleText"] = "Det her er\nGULDKLUMP-BROEN!\nHvis du besejrer\nos fem trænere, \nfår du en\nværdifuld præmie!\nVil du prøve\ndin lykke?",
    ["_Route24Youngster2EndBattleText"] = "Wow!\nDu er god!",
    ["_Route25BillSignText"] = "KYSTHUS\nHer bor BILL!",
    ["_Route25CooltrainerF1AfterBattleText"] = "Ak, gid min\nkæreste var\nogså så god som\ndig!",
    ["_Route25CooltrainerF1BattleText"] = "Hej! Min\nkæreste er sej!",
    ["_Route25CooltrainerF1EndBattleText"] = "Jeg var\nikke i form!",
    ["_Route25CooltrainerF2AfterBattleText"] = "Var du på\nMÅNEBJERGET? Fandt\ndu en CLEFAIRY?",
    ["_Route25CooltrainerF2BattleText"] = "Min kæreste\nhar sådan en\nsød POKéMON! Jeg\ner forfærdelig\nmisundelig!",
    ["_Route25CooltrainerF2EndBattleText"] = "Jeg er\nikke misundelig!",
    ["_Route25CooltrainerMAfterBattleText"] = "Nå, min\nkæreste vil\nopmuntre mig!",
    ["_Route25CooltrainerMBattleText"] = "Jeg er virkelig\nsej! Jeg har\nen kæreste!",
    ["_Route25CooltrainerMEndBattleText"] = "Åh,\nsikke et uheld...",
    ["_Route25Hiker1AfterBattleText"] = "Pokkers!\nEn ZUBAT bed\nmig!",
    ["_Route25Hiker1BattleText"] = "Jeg kommer lige\nfra MÅNEBJERGET\nog er topfit!",
    ["_Route25Hiker1EndBattleText"] = "Du har\nkæmpet hårdt!",
    ["_Route25Hiker2AfterBattleText"] = "Denne samler\nejer mange\nsjældne POKéMON.",
    ["_Route25Hiker2BattleText"] = "Jeg er på\nvej til en\nPOKéMON-samler!",
    ["_Route25Hiker2EndBattleText"] = "Du har\nbesejret mig.",
    ["_Route25Hiker3AfterBattleText"] = "Stien dernede\ner en genvej\ntil CERULEAN\nCITY.",
    ["_Route25Hiker3BattleText"] = "Vil du til\nBILL? Men først\nkæmper vi!",
    ["_Route25Hiker3EndBattleText"] = "Du har\nmeget erfaring!",
    ["_Route25Youngster1AfterBattleText"] = "Ethvert POKéMON\nhar sine svagheder!\nMan bør derfor\ntræne\nforskellige\nPOKéMON.",
    ["_Route25Youngster1BattleText"] = "Trænerne i\nomegnen kommer\nherhen for at\nøve sig!",
    ["_Route25Youngster1EndBattleText"] = "Du er\nvirkelig god!",
    ["_Route25Youngster2AfterBattleText"] = "På M.S. ANNE\nhar jeg set\ntrænere fra\nhele verden!",
    ["_Route25Youngster2BattleText"] = "Jeg var i\nVERMILION CITY med\nmin far til en\nfest på\nM.S. ANNE!",
    ["_Route25Youngster2EndBattleText"] = "Jeg er\nikke sur!",
    ["_Route25Youngster3AfterBattleText"] = "Hvis en af dine\nPOKéMON er\nforvirret eller\nsover, så skift\ndet ud!",
    ["_Route25Youngster3BattleText"] = "Jeg vidste, at\nvi ville\nkæmpe mod hinanden!",
    ["_Route25Youngster3EndBattleText"] = "Jeg\nvidste også, at\njeg ville\ntabe!",
    ["_Route2DiglettsCaveSignText"] = "DIGLETTS HULE",
    ["_Route2GateOaksAideFlashExplanationText"] = "Med VM BLITZ\nkan man selv\noplyse de\nmørkeste huler.",
    ["_Route2GateYoungsterText"] = "Så snart en af\ndine POKéMON\nhar lært BLITZ,\nkan du vove\ndig ind i\nKLIPPETUNNELEN!",
    ["_Route2SignText"] = "RUTE 2\nVIRIDIAN CITY -\nPEWTER CITY",
    ["_Route2TradeHouseScientistText"] = "Selv når en\nPOKéMON\nudgår,\nkan det stadig\nbruge special-\nteknikker som\nfor eksempel\nSKÆRER!",
    ["_Route3CooltrainerF1AfterBattleText"] = "Hold op med at\nstirre på folk!\nSå behøver du\nheller ikke\nkæmpe!",
    ["_Route3CooltrainerF1BattleText"] = "Hvad glor du\nsådan på mig\nfor?",
    ["_Route3CooltrainerF1EndBattleText"] = "Du er\nfarlig!",
    ["_Route3CooltrainerF2AfterBattleText"] = "Undgå kampe\nved at gå\nuden om andre\ntrænere!",
    ["_Route3CooltrainerF2BattleText"] = "Hvorfor ser\ndu så\nfascineret på mig?",
    ["_Route3CooltrainerF2EndBattleText"] = "Vær\naltid flink!",
    ["_Route3CooltrainerF3AfterBattleText"] = "RUTE 4 ligger\nved foden af\nMÅNEBJERGET.",
    ["_Route3CooltrainerF3BattleText"] = "Hovsa! Skal det\nvære en\ntilnærmelse?",
    ["_Route3CooltrainerF3EndBattleText"] = "\nHold dig fra mig!",
    ["_Route3SignText"] = "RUTE 3\nTIL MÅNEBJERGET",
    ["_Route3Text1"] = "Puh! Jeg må\ntage en\npause!\nVejen gennem\ntunnelen fra CERULEAN\nCITY er meget\nbesværlig!",
    ["_Route3Youngster1AfterBattleText"] = "Foruden POKéMON\nher i skoven\nfindes der\nutallige andre\nPOKéMON at\nopdage!",
    ["_Route3Youngster1BattleText"] = "Hey! Jeg kender\ndig fra\nVIRIDIAN-SKOVEN!",
    ["_Route3Youngster1EndBattleText"] = "Du\nhar besejret mig\nigen!",
    ["_Route3Youngster2AfterBattleText"] = "Du kan lægge\nPOKéMON i bokse\nvia PC. Hver BOKS\nrummer 20 POKéMON!",
    ["_Route3Youngster2BattleText"] = "Overalt er der\nnælder! Og jeg\nhar shorts på!\nSIKKE ET UHELD!",
    ["_Route3Youngster2EndBattleText"] = "Var\njeg dog blot\nblevet hjemme\ni dag!",
    ["_Route3Youngster3AfterBattleText"] = "Når en POKéMON-\nBOKS er fuld på\nPC'en, skift så\nbare til en\nanden BOKS!",
    ["_Route3Youngster3BattleText"] = "Er du også en\ntræner? Lad os\nkæmpe!",
    ["_Route3Youngster3EndBattleText"] = "Med\ndisse POKéMON\nville jeg også\nnemt have vundet!",
    ["_Route3Youngster4AfterBattleText"] = "Man burde ikke\ngøre alt, hvad\nstorebror\nforlanger! Hehe!",
    ["_Route3Youngster4BattleText"] = "Hehe! Jeg sagde\ntil min bror,\nhan skulle\ntage shorts på!",
    ["_Route3Youngster4EndBattleText"] = "Nej!\nTabt!",
    ["_Route3Youngster5AfterBattleText"] = "En træners\nPOKéMON er\nstærkere end\nvilde!",
    ["_Route3Youngster5BattleText"] = "Mine nye\nPOKéMON vil\nkæmpe!",
    ["_Route3Youngster5EndBattleText"] = "Du\nhar besejret\nmine POKéMON!",
    ["_Route4CooltrainerF1Text"] = "Av! Jeg snublede\nover en\nGEODUDE, et\nSTEN-POKéMON!",
    ["_Route4CooltrainerF2AfterBattleText"] = "Der burde ikke\nvære flere SVAMP-\nPOKéMON her.\nJeg tror, jeg\nhar fanget dem\nalle.",
    ["_Route4CooltrainerF2BattleText"] = "Jeg er her for\nat fange SVAMP-\nPOKéMON!",
    ["_Route4CooltrainerF2EndBattleText"] = "Åh,\nSVAMP-POKéMON\ner jo så søde!",
    ["_Route4MtMoonSignText"] = "MÅNEBJERGET\nTunnelindgang",
    ["_Route4SignText"] = "RUTE 4\nMÅNEBJERGET -\nCERULEAN CITY",
    ["_Route5UndergroundPathSignText"] = "TUNNELSTI\nCERULEAN CITY -\nVERMILION CITY",
    ["_Route6CooltrainerAfterBattleText"] = "Hvisken...\nMumlen...",
    ["_Route6CooltrainerF1BattleText"] = "Undskyld,\nmen det her er\nprivat!",
    ["_Route6CooltrainerF1EndBattleText"] = "\nGrr! Jeg hader\nat tabe!",
    ["_Route6CooltrainerF2AfterBattleText"] = "Vil du fortælle\nmig din hemmelighed?\nJeg vil også\ngerne blive\nstærkere!",
    ["_Route6CooltrainerF2BattleText"] = "Kæmpe? Mener du\nmig? Nå, godt!",
    ["_Route6CooltrainerF2EndBattleText"] = "\nDet lykkedes ikke\nhelt!",
    ["_Route6CooltrainerM1BattleText"] = "Hvem der? Hey,\nhold op med at\nlytte hemmeligt\nmed!",
    ["_Route6CooltrainerM1EndBattleText"] = "Jeg\nkan simpelthen\naldrig vinde!",
    ["_Route6CooltrainerM2AfterBattleText"] = "For min egen\nsikkerheds skyld\nburde jeg bære\nflere POKéMON\nmed mig!",
    ["_Route6CooltrainerM2BattleText"] = "Hørte jeg\nnogen tale om\nkamp?",
    ["_Route6CooltrainerM2EndBattleText"] = "Hmm,\njeg burde have\noverhørt det!",
    ["_Route6UndergroundPathSignText"] = "TUNNELSTI\nCERULEAN CITY -\nVERMILION CITY",
    ["_Route6Youngster1AfterBattleText"] = "Jeg går tilbage\ntil VIRIDIAN-\nSKOVEN. Der er\nflere insekter!",
    ["_Route6Youngster1BattleText"] = "Man finder ikke\nmange insekter\nherude...",
    ["_Route6Youngster1EndBattleText"] = "\nDu spøger vel,\nikke?",
    ["_Route6Youngster2AfterBattleText"] = "Er mine\nPOKéMON for\nsvage, eller er\njeg måske ikke\ngod nok?",
    ["_Route6Youngster2BattleText"] = "Dig har jeg\naldrig set før!\nEr du en god\ntræner?",
    ["_Route6Youngster2EndBattleText"] = "Du\ner en for god\ntræner!",
    ["_Route7UndergroundPathSignText"] = "TUNNELSTI\nCELADON CITY -\nLAVENDER TOWN",
    ["_Route8CooltrainerF1AfterBattleText"] = "Når POKéMON\nudvikler sig,\nbliver de store\nog grimme! De\nburde forblive\nsmå og søde!",
    ["_Route8CooltrainerF1BattleText"] = "Jeg kan lide\nalle NIDORAN\nrigtig meget!\nDerfor samler\njeg dem!",
    ["_Route8CooltrainerF1EndBattleText"] = "Hvorfor?\nHvorfor dog?",
    ["_Route8CooltrainerF2AfterBattleText"] = "Men PIDGEY og\nRATTATA er\nogså søde!",
    ["_Route8CooltrainerF2BattleText"] = "MEOWTH er så sød!\nMjav, mjauz!",
    ["_Route8CooltrainerF2EndBattleText"] = "Mjauz!",
    ["_Route8CooltrainerF3AfterBattleText"] = "Vagten i\nSAFFRON\nCITY er så\nled! Han lader\nos ikke komme\nind i byen!",
    ["_Route8CooltrainerF3BattleText"] = "Det må se\nganske fjollet\nud, at vi står\nher!",
    ["_Route8CooltrainerF3EndBattleText"] = "Se, hvad\ndu har gjort!",
    ["_Route8CooltrainerF4AfterBattleText"] = "Jeg har hørt,\nat CLEFAIRY\nudvikler sig, hvis\nman giver den\nen MÅNESTEN.",
    ["_Route8CooltrainerF4BattleText"] = "Hvilket POKéMON\ner sødt, buttet\nog hyggeligt?",
    ["_Route8CooltrainerF4EndBattleText"] = "Hold op!\nVær ikke så\nled ved CLEFAIRY!",
    ["_Route8Gambler1AfterBattleText"] = "Man kan ikke\naltid vinde!",
    ["_Route8Gambler1BattleText"] = "OK! Spillene\nkan begynde!",
    ["_Route8Gambler1EndBattleText"] = "\nKnapt forbi er\nogså ved siden af!",
    ["_Route8Gambler2AfterBattleText"] = "Hasardspil og\nPOKéMON har\nén ting til\nfælles: Man kan\nikke holde op\nmed det!",
    ["_Route8Gambler2BattleText"] = "Jeg er en\nvidt berejst\nhasardspiller!",
    ["_Route8Gambler2EndBattleText"] = "\nJackpotten har\njeg endnu ikke\nknækket...",
    ["_Route8SuperNerd1AfterBattleText"] = "Mine\nskolepræstationer\ner bedre!",
    ["_Route8SuperNerd1BattleText"] = "Du ved meget\nom POKéMON!\nMen hvordan\ngår det med kemi?",
    ["_Route8SuperNerd1EndBattleText"] = "Av! En\nkernesmeltning!",
    ["_Route8SuperNerd2AfterBattleText"] = "GRIMER kæmper som\ndet første... og...\nog... så...",
    ["_Route8SuperNerd2BattleText"] = "For at vinde\nskal du bruge\nen god strategi!",
    ["_Route8SuperNerd2EndBattleText"] = "Jeg har\ntabt! Det er\nikke logisk!",
    ["_Route8SuperNerd3AfterBattleText"] = "Vi sidder fast\nher, fordi\nSAFFRON CITY\ner lukket af.",
    ["_Route8SuperNerd3BattleText"] = "Skolen er sjov!\nMen at træne\nPOKéMON også!",
    ["_Route8SuperNerd3EndBattleText"] = "OK, jeg\ngår hellere i\nskole!",
    ["_Route8UndergroundSignText"] = "TUNNELSTI\nCELADON CITY -\nLAVENDER TOWN",
    ["_Route9CooltrainerF1AfterBattleText"] = "Du skal bruge\nen lyskilde for\nat komme igennem\ntunnelen!",
    ["_Route9CooltrainerF1BattleText"] = "Du bærer POKéMON\nmed dig! Lad os\nkæmpe!",
    ["_Route9CooltrainerF1EndBattleText"] = "Du\nhar vundet!",
    ["_Route9CooltrainerF2AfterBattleText"] = "Du har meget\ntalent! Held og\nlykke på din\nvidere vej!",
    ["_Route9CooltrainerF2BattleText"] = "Tør du godt\nkæmpe mod\nmig?",
    ["_Route9CooltrainerF2EndBattleText"] = "Det\nvar for meget af\ndet gode!",
    ["_Route9CooltrainerM1AfterBattleText"] = "OK, gå bare\nvidere!",
    ["_Route9CooltrainerM1BattleText"] = "Hey, hvem er du?\nDine POKéMON\nser fit ud!",
    ["_Route9CooltrainerM1EndBattleText"] = "\nHurtigt og\npræcist besejret!",
    ["_Route9CooltrainerM2AfterBattleText"] = "Vil du også\nbruge\nKLIPPETUNNELEN?",
    ["_Route9CooltrainerM2BattleText"] = "Jeg går gennem\nKLIPPETUNNELEN\ntil LAVENDER TOWN...",
    ["_Route9CooltrainerM2EndBattleText"] = "\nMed dig har jeg\novervurderet mig\nselv!",
    ["_Route9Hiker1AfterBattleText"] = "Dine knæ rystede\nvel ganske\ngodt, ikke sandt?",
    ["_Route9Hiker1BattleText"] = "Endelig\nkommer der nogen!\nJeg var virkelig\nved at kede\nmig!",
    ["_Route9Hiker1EndBattleText"] = "Var det\nallerede alt?\nÅh! Jeg har\ningen kampklare\nPOKéMON tilbage!",
    ["_Route9Hiker2AfterBattleText"] = "Haha! Børn\nburde være\nsmå rakkerunger!",
    ["_Route9Hiker2BattleText"] = "Du har\ningen chance, din\nlille rakkerunge!",
    ["_Route9Hiker2EndBattleText"] = "Hvad\nskete der?",
    ["_Route9Hiker3AfterBattleText"] = "Haha!\nVi spøgefugle\nler konstant!",
    ["_Route9Hiker3BattleText"] = "Ha! Hvad\nsiger du til en\nkamp?",
    ["_Route9Hiker3EndBattleText"] = "Haha!\nEn fair kamp!",
    ["_Route9SignText"] = "RUTE 9\nCERULEAN CITY -\nKLIPPETUNNEL",
    ["_Route9Youngster1AfterBattleText"] = "Jeg burde\nhellere samle\net par stærkere...",
    ["_Route9Youngster1BattleText"] = "Jeg står op\ntidligt hver\ndag for at\npasse mine\nPOKéMON i\nderes kokon!",
    ["_Route9Youngster1EndBattleText"] = "HVAD?\nDet var\nren spild af\ntid!",
    ["_Route9Youngster2AfterBattleText"] = "Den, der ikke\nkan lide insekter,\nkan jeg heller\nikke lide!",
    ["_Route9Youngster2BattleText"] = "Du har\ningen chance mod\nmine INSEKT-\nPOKéMON!",
    ["_Route9Youngster2EndBattleText"] = "\nMine\nINSEKT-POKéMON...",
    ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "Sådan behandler\nman ikke POKéMON\naf verdensklasse!\nJeg kræver en\nbehandling i et \nPKMN-CENTER for\nmine POKéMON!!!",
    ["_SSAnne1FRoomsCooltrainerFBattleText"] = "På mine rejser\nrundt om verden\nhar jeg fanget\nutallige POKéMON!",
    ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "Nej!\nJeg har rejst\nhele verden\nrundt for\ndisse POKéMON!",
    ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "Vær altid flink\nved dine POKéMON!",
    ["_SSAnne1FRoomsGentleman1BattleText"] = "Jeg holder altid\nferie alene!\nKun mine POKéMON\nfølger mig!",
    ["_SSAnne1FRoomsGentleman1EndBattleText"] = "Åh\nnej, tabt!",
    ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "Jeg vil have min\nfred!\nForsvind!",
    ["_SSAnne1FRoomsGentleman2BattleText"] = "Din snothvalp! Hvad\ntænker du på?",
    ["_SSAnne1FRoomsGentleman2EndBattleText"] = "Pokkers!\nDu er ganske\ngod!",
    ["_SSAnne1FRoomsGentleman3Text"] = "Pst! Jeg er\nen hemmelig agent!\nJeg forfølger\nTEAM ROCKET! Pst!",
    ["_SSAnne1FRoomsGirl1Text"] = "Steward, jeg\nvil gerne have et\nstykke lagkage!",
    ["_SSAnne1FRoomsGirl2Text"] = "Vi tager på en\nstor jordomrejse!",
    ["_SSAnne1FRoomsLittleGirlText"] = "Jeg rejser altid\nmed WIGGLYTUFF!",
    ["_SSAnne1FRoomsMiddleAgedManText"] = "Ah, sikke et\nvidunderligt\nkrydstogt!",
    ["_SSAnne1FRoomsWigglytuffText"] = "WIGGLYTUFF: \nKnuddel! Knuddel!",
    ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "Lad os blive\nvenner, OK?\nSå kan vi\nbytte POKéMON!",
    ["_SSAnne1FRoomsYoungsterBattleText"] = "Jeg er totalt\nvild med POKéMON!\nEr du også?",
    ["_SSAnne1FRoomsYoungsterEndBattleText"] = "Wow! Du\ner sej!",
    ["_SSAnne1FSailorText"] = "Mange passagerer\ner hyperaktive!\nDe keder sig\nog længes\nefter en kamp!",
    ["_SSAnne1FWaiterText"] = "Godmorgen, dig\nlandkrabbe! Jeg\ner stewarden\npå dette\nskib!\nKald mig bare,\nhvis du har\net ønske!\nFandens,\nsnaksalig er du\nnu ikke!",
    ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}: Der\nskal angiveligt\nvære en stor\nmester i brugen\naf SKÆRER om\nbord.\nMen der var kun\nen søsyg\ngammel mand!\nSKÆRER er\nekstremt\nnyttig!\nDu burde\nbesøge den\ngamle mand! Ciao!",
    ["_SSAnne2FRivalDefeatedText"] = "Pokkers!\nNå, i det mindste\ntræner du dine\nPOKéMON!",
    ["_SSAnne2FRivalText"] = "{RIVAL}: Se der!\n{PLAYER}!\nJeg vidste, jeg\nville møde dig\nher!\n{PLAYER}, blev\ndu virkelig\ninviteret?\nHvordan går det\nmed din\nPOKéDEX?\nJeg har allerede\nfanget 40\nforskellige\nPOKéMON!\nDer findes en\nkæmpe mangfoldighed\naf POKéMON!\nPrøv din\nlykke i højt\ngræs!",
    ["_SSAnne2FRivalVictoryText"] = "{PLAYER}! Er du\nmon søsyg?\nDu burde\nkomme i form, \nmakker!",
    ["_SSAnne2FRoomsBeautyText"] = "Mange mennesker\nbliver let søsyge!",
    ["_SSAnne2FRoomsBrunetteGirlText"] = "KAPTAJNEN var\nkridhvid! Han\nså dårlig ud!",
    ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "Jeg beundrer\ndine POKéMONs\nstyrke!",
    ["_SSAnne2FRoomsCooltrainerFBattleText"] = "Hvor var du, da\nfesten kørte?",
    ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "Tag det\nlige roligt!!!",
    ["_SSAnne2FRoomsFisherAfterBattleText"] = "En fest?\nDen er nok for\nlængst overstået. Du\ner sent på den!",
    ["_SSAnne2FRoomsFisherBattleText"] = "Se, hvad jeg\nhar trukket op\npå land!",
    ["_SSAnne2FRoomsFisherEndBattleText"] = "OK!\nDet var det for\nmig! Farvel!!!",
    ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "For 15 år siden\nville jeg have\nvundet med\nlethed...",
    ["_SSAnne2FRoomsGentleman1BattleText"] = "I konkurrence\nmed ungdommen\nforbliver jeg\nung!",
    ["_SSAnne2FRoomsGentleman1EndBattleText"] = "Ahhh!\nSådan føler man\nsig straks yngre!",
    ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "Jeg kan lide\nPOKéMON, der er\nstærke og\nsjældne!",
    ["_SSAnne2FRoomsGentleman2BattleText"] = "Hvad kan du bedst\nlide? Stærke\neller sjældne\nPOKéMON?",
    ["_SSAnne2FRoomsGentleman2EndBattleText"] = "Jeg\ntager hatten\naf for dig! Wow!",
    ["_SSAnne2FRoomsGentleman3Text"] = "På alle mine\nrejser har jeg\naldrig set en\nså søvnig\nPOKéMON!\nDet ser cirka\nsådan ud...",
    ["_SSAnne2FRoomsGentleman4Text"] = "Jeg har allerede\nset folk glide\nover vandet på\nPOKéMON!",
    ["_SSAnne2FRoomsGentleman5Text"] = "Har du allerede\nbesøgt\nSAFARI-ZONEN i\nFUCHSIA CITY?\nDer findes meget\nsjældne POKéMON!",
    ["_SSAnne2FRoomsGrampsText"] = "POKéMON kan\nhugge buske\nned med\nSKÆRER.",
    ["_SSAnne2FRoomsLittleBoyText"] = "Min far var med\nmig i\nSAFARI-ZONEN! Det\nvar spændende!",
    ["_SSAnne2FWaiterText"] = "Dette luksuriøse\ndrømmeskib sejler\nudelukkende for\ntrænere til søs!\nI hver havn\nbesøger kun\ninviterede\ntrænere os!",
    ["_SSAnne3FSailorText"] = "KAPTAJNEN er\nen mester i\nsværdkamp!\nHan lærer endda\nPOKéMON at\nbruge\nSKÆRER!",
    ["_SSAnneB1FRoomsFisherAfterBattleText"] = "Jeg havde\nnæsten gjort dig\ntil assistent!",
    ["_SSAnneB1FRoomsFisherBattleText"] = "Vent nu lidt!\nLad os snakke!\nJeg ejer kun\nVAND-POKéMON!",
    ["_SSAnneB1FRoomsFisherEndBattleText"] = "Pokkers!\nDen slap fra\nmig!",
    ["_SSAnneB1FRoomsMachokeText"] = "MACHOP: Macho!\nMachollo!",
    ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "Vil du blive\nsømand, lille ven?",
    ["_SSAnneB1FRoomsSailor1BattleText"] = "Du ved, vi\nsømænd elsker\nat kæmpe!",
    ["_SSAnneB1FRoomsSailor1EndBattleText"] = "JA! Sikke\nen kamp!!!",
    ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "Har du allerede\nbesøgt PROFFISKEREN\ni VERMILION CITY?",
    ["_SSAnneB1FRoomsSailor2BattleText"] = "Mit ry som\nsøulk står på\nspil!!!",
    ["_SSAnneB1FRoomsSailor2EndBattleText"] = "\nKøl under! Det\nvar det for mig!",
    ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "Sømænd fanger\nderes POKéMON på\ndet åbne hav!",
    ["_SSAnneB1FRoomsSailor3BattleText"] = "Også sømænd\nejer POKéMON!",
    ["_SSAnneB1FRoomsSailor3EndBattleText"] = "Det var\nen moden\npræstation!",
    ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "VAND-POKéMON\nlever under\nvandet! Du\nskal bruge en\nFISKESTANG!",
    ["_SSAnneB1FRoomsSailor4BattleText"] = "Jeg var før\nlige så\nopstemt som\ndig!",
    ["_SSAnneB1FRoomsSailor4EndBattleText"] = "Åh nej!\nTabt!",
    ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "Nogle gange\ndriver vandmænd\nmod skibet. Kokken\nfanger dem så...",
    ["_SSAnneB1FRoomsSailor5BattleText"] = "Taberen\nfår kølhaling!\nSå går det løs!",
    ["_SSAnneB1FRoomsSailor5EndBattleText"] = "Argh!\nBesejret af\net barn...",
    ["_SSAnneB1FRoomsSuperNerdText"] = "Mit POKéMON,\nMACHOP, er\nsuperstærk!!!\nMed sin STYRKE\nkan den endda\nflytte klipper!",
    ["_SSAnneBowCooltrainerMText"] = "Brrr, jeg\nfår det dårligt...\nI frisk luft\nfår jeg det\nbedre...",
    ["_SSAnneBowSailor1Text"] = "Puh! Jeg får\naldrig dækket\nrent!",
    ["_SSAnneBowSailor2AfterBattleText"] = "Har du nogen\nidé om, hvor\nmange forskellige\nPOKéMON der findes?",
    ["_SSAnneBowSailor2BattleText"] = "Hey!\nHvad med en\ndans?",
    ["_SSAnneBowSailor2EndBattleText"] = "Jeg er\nimponeret!",
    ["_SSAnneBowSailor3AfterBattleText"] = "Min far siger,\nder findes 100\nforskellige \nPOKéMON. Jeg\ntror, der\nfindes flere...",
    ["_SSAnneBowSailor3BattleText"] = "Ahoy, sømand!\nEr du søsyg?",
    ["_SSAnneBowSailor3EndBattleText"] = "Du havde\nheld med dig!",
    ["_SSAnneBowSuperNerdText"] = "Lukketid! Festen\ner slut!\nSkibet stikker\nsnart til søs!",
    ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "Åh, nej! Du har\nikke plads til\nflere items!",
    ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "KAPTAJN: Ahhhhh!\nMange tak!\nJeg har det\nallerede meget\nbedre...\nVil du lære at\nbruge\nSKÆRER?\nJeg kunne lære\ndig det, men\njeg har det så\ndårligt.\nJeg har det! Tag\nbare den her!\nMed den kan du\nlære dine POKéMON\nnemt at bruge\nSKÆRER!",
    ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "KAPTAJN: Super!\nEndelig er jeg\nikke syg længere!\nNu kan vi\nsejle!",
    ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "{PLAYER} modtager\n{RAM:wStringBuffer}!",
    ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "KAPTAJN: Urgh...\nJeg har det\nslet ikke godt! Urgh!\n{PLAYER} masserer\nKAPTAJNENS\nryg!\nGnub...\nSkrub...",
    ["_SSAnneCaptainsRoomSeasickBookText"] = "1000 naturlige\nhjemmemidler mod\nsøsyge...\nKAPTAJNEN læser\ndenne bog!",
    ["_SSAnneCaptainsRoomTrashText"] = "Buæh! Nogle\nting gør man\nbedre ikke...",
    ["_SSAnneKitchenCook1Text"] = "Af vejen, din\nulastede matros!\nVi er meget\ntravlt optaget!",
    ["_SSAnneKitchenCook2Text"] = "Jeg har set en\nmærkelig bold i\nskraldespanden...",
    ["_SSAnneKitchenCook3Text"] = "Der er for meget\nat gøre, jeg kan\naldrig hvile mig!",
    ["_SSAnneKitchenCook4Text"] = "Hvad har jeg\ndog gjort galt?\nJeg skal altid\nbare skrælle\nkartofler...",
    ["_SSAnneKitchenCook5Text"] = "Har du allerede\nhørt om SNORLAX?\nDen sover og\nspiser hele\ndagen!",
    ["_SSAnneKitchenCook6Text"] = "Snøft... \n...snøft...\nJeg skal altid\nskrælle\nløgene...",
    ["_SSAnneKitchenCook7MainCourseIsText"] = "Jeg er\nkøkkenchefen! \nHovedretten er",
    ["_SSTicketNoRoomText"] = "Hey makker, du\nbærer for meget\nmed dig!",
    ["_SSTicketReceivedText"] = "{PLAYER} modtager\net {RAM:wStringBuffer}!",
    ["_SafariZoneAngryText"] = "Den vilde\n{RAM:wEnemyMonNick} er\nvred!",
    ["_SafariZoneCenterRestHouseGirlText"] = "SARAH: Hvor er\nmin kæreste\nERIK dog gået hen?",
    ["_SafariZoneCenterRestHouseScientistText"] = "Når jeg fanger\nPOKéMON, forærer\njeg dem væk, når\njeg er tilbage\nhjemme!",
    ["_SafariZoneCenterRestHouseSignText"] = "HVILEHUS",
    ["_SafariZoneCenterTrainerTipsSignText"] = "TIPS TIL TRÆNERE\nTryk på START for\nat se, hvor\nmeget tid du\nhar tilbage!",
    ["_SafariZoneEastRestHouseRockerText"] = "Jeg har fanget\net CHANSEY!\nUmagen har\nløn net sig!",
    ["_SafariZoneEastRestHouseScientistText"] = "Hvor mange har\ndu fanget? Jeg\ner totalt udmattet!",
    ["_SafariZoneEastRestHouseSignText"] = "HVILEHUS",
    ["_SafariZoneEastRestHouseSilphWorkerMText"] = "Sikke en sjov!\nMen nu er jeg\nhundetræt...",
    ["_SafariZoneEastSignText"] = "CENTRUM\nNORD: OMRÅDE 2",
    ["_SafariZoneEastTrainerTipsText"] = "TIPS TIL TRÆNERE\nDen resterende\ntid går kun,\nmens du\ngår!",
    ["_SafariZoneEatingText"] = "Den vilde\n{RAM:wEnemyMonNick} spiser!",
    ["_SafariZoneGateSafariZoneWorker1CallYouOnThePAText"] = "\nVi kalder dig\nover HØJTALEREN,\nnår din\nfangsttid er\nudløbet, eller\ndit forråd af\nSAFARIBALLE\ner opbrugt!",
    ["_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText"] = "Var jagten\nvellykket?\nBesøg os snart\nigen!",
    ["_SafariZoneGateSafariZoneWorker1GoodLuckText"] = "Held og lykke!",
    ["_SafariZoneGateSafariZoneWorker1LeavingEarlyText"] = "Har du ikke\nlyst mere?",
    ["_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText"] = "Ups! Du har\nikke nok penge!",
    ["_SafariZoneGateSafariZoneWorker1PleaseComeAgainText"] = "OK! Besøg\nos snart igen!",
    ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "Aflever venligst\nde resterende\nSAFARIBALLE\ntilbage.",
    ["_SafariZoneGateSafariZoneWorker1Text"] = "Velkommen til\nSAFARI-ZONEN!",
    ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "Det koster\n¥500!\nVi bruger\nspecielle\nPOKéBALLE her.\n{PLAYER} modtager\n30 SAFARIBALLE!",
    ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "For kun ¥500\nmå du fange så\nmange POKéMON i\nparken, som du\nvil!\nVil du gå\npå jagt?",
    ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "Hej! Er du her\nfor første gang?",
    ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "SAFARI-ZONEN\nbestår af fire\nområder.\nI hvert\nområde finder\nman forskellige\nPOKéMON.\nPrøv at fange\ndem med\nSAFARIBALLE.\nHvis du ikke\nhar flere\nSAFARIBALLE eller\nhvis tiden\ner udløbet,\nslutter spillet!\nFør du drager på\njagt, bør du\nskabe plads til\nnye POKéMON og\nvælge en fri\nPOKéMON-BOKS!",
    ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "Hey, du er en\nfast kunde!",
    ["_SafariZoneNorthRestHouseGentlemanText"] = "Min EEVEE har\nudviklet sig til\nFLAREON!\nMen hos en\nven udviklede\nEEVEE sig til\nVAPOREON!",
    ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "Tag til\nSAFARI-ZONEN!\nDer kan du\nvinde en\npræmie!",
    ["_SafariZoneNorthRestHouseScientistText"] = "Alle items,\ndu finder,\ntilhører dig!\nMen tiden vil\nløbe fra dig,\nhvis du vil\nsamle dem alle\npå én gang!",
    ["_SafariZoneNorthRestHouseSignText"] = "HVILEHUS",
    ["_SafariZoneNorthSignText"] = "OMRÅDE 2",
    ["_SafariZoneNorthTrainerTips1Text"] = "TIPS TIL TRÆNERE\nDer er ikke\nlangt til det\nHEMMELIGE HUS!",
    ["_SafariZoneNorthTrainerTips2Text"] = "TIPS TIL TRÆNERE\nPOKéMON\ngemmer sig i\nhøjt græs!\nGå gennem det\nhøje græs og\nskræm dem op!",
    ["_SafariZoneNorthTrainerTips3Text"] = "TIPS TIL TRÆNERE\nFind det\nSKJULTE HUS.\nSå vinder du\nen VM!",
    ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "VM03 er SURFER!\nLærer en POKéMON\ndenne teknik,\nkan det bære\ndig over\nvandet!\nDet BEDSTE er\ndog, at du kan\nbruge denne VM\nlige så mange\ngange, du vil!\nEr det ikke\nvildt? Du er\nheldig!",
    ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "Åh! Du kan ikke\nbære flere\nitems!",
    ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "{PLAYER} modtager\n{RAM:wStringBuffer}!",
    ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "Ah! Endelig!\nDu er den\nførste, der har\nfundet det\nSKJULTE HUS!\nJeg troede\nallerede, ingen\nnogensinde ville\nvinde\nhovedpræmien!\nTillykke! Du\nhar vundet!",
    ["_SafariZoneWestFindWardensTeethSignText"] = "BELØNNING!\nDen, der finder\nSAFARI-ZONENS\nparkvogters\nGULDTÆNDER,\nmodtager en\nbelønning!\nFindere bedes\nmelde sig hos\nparkvogteren!",
    ["_SafariZoneWestRestHouseCooltrainerMText"] = "Hvis du kaster\nAGN til dem,\ner POKéMON\nlettere at\nfange!",
    ["_SafariZoneWestRestHouseScientistText"] = "Hvis du kaster\nSTEN på POKéMON,\nflygter de\nsom regel. Men\nde er så\nlettere at\nfange!",
    ["_SafariZoneWestRestHouseSignText"] = "HVILEHUS",
    ["_SafariZoneWestRestHouseSilphWorkerFText"] = "Jeg har søgt\nlænge, men\nfandt ingen\nnye POKéMON.",
    ["_SafariZoneWestSignText"] = "OMRÅDE 3\nØST: CENTRUM",
    ["_SafariZoneWestTrainerTipsText"] = "TIPS TIL TRÆNERE\nUdforsk\nSAFARI-ZONEN!\nFind det\nSKJULTE HUS!",
    ["_SaffronCityFightingDojoSignText"] = "KAMP-DOJO",
    ["_SaffronCityGentlemanText"] = "Jeg fløj hertil\nmed min PIDGEOT,\nefter jeg havde\nlæst om\nSILPH CO.!\nEr det allerede\noverstået? Nå ja,\nså har jeg vel\ngået glip af\ndet bedste!",
    ["_SaffronCityGymSignText"] = "SAFFRON CITY\nPKMN-ARENA\nARENALEDER: \nSABRINA\nHerskerinden over\nPSYKO-POKéMON!",
    ["_SaffronCityMrPsychicsHouseSignText"] = "PSYKOLOGENS HUS",
    ["_SaffronCityPidgeotText"] = "PIDGEOT: Tauboss!",
    ["_SaffronCityPokecenterGuyText1"] = "Jeg ville ønske,\nTOP FIRE kom\nog stampede\nTEAM ROCKET\nned i jorden!",
    ["_SaffronCityPokecenterGuyText2"] = "TEAM ROCKET\ner flygtet! Vi\nkan igen gå\nud af huset!",
    ["_SaffronCityRockerText"] = "CHEFEN for\nTEAM ROCKET er\nflygtet fra\nSILPH CO.'s\nbygning!",
    ["_SaffronCityRocket1Text"] = "Hvad vil du\nmere? Skrid!",
    ["_SaffronCityRocket2Text"] = "CHEFEN har\nlovet, at vi\nvil indtage\ndenne by.",
    ["_SaffronCityRocket3Text"] = "Mand, gå af\nvejen!",
    ["_SaffronCityRocket4Text"] = "SAFFRON CITY\ntilhører TEAM\nROCKET!",
    ["_SaffronCityRocket5Text"] = "Jeg føler mig\nvidunderlig, når\njeg er ond!",
    ["_SaffronCityRocket6Text"] = "Av! Pas på,\nhvor du går!",
    ["_SaffronCityRocket7Text"] = "Når vi først har\nSILPH CO. under\nkontrol, kan vi\nhandle med\nPOKéMON i hele\nverden!",
    ["_SaffronCityRocket8Text"] = "Jeg er\nvagten.\nMistænkelige\nbørn lader jeg\nikke komme ind!",
    ["_SaffronCityRocket9Text"] = "...\nSnorke...\nHa! Han tager\nsig en lur!",
    ["_SaffronCityScientistText"] = "Har du besejret\nTEAM ROCKET?\nUtroligt!!!",
    ["_SaffronCitySignText"] = "SAFFRON CITY.\nDen guldskinnende\nhandelsby!",
    ["_SaffronCitySilphCoLatestProductSignText"] = "SILPH CO.'s\nnyeste\nprodukt!\nSalgsstart:\nSnart!",
    ["_SaffronCitySilphCoSignText"] = "SILPH CO.\nKONTORBYGNING",
    ["_SaffronCitySilphWorkerFText"] = "Nu kommer der\nogså igen turister\ntil SAFFRON\nCITY!",
    ["_SaffronCitySilphWorkerMText"] = "Hurra! TEAM\nROCKET er væk!\nNu føler man\nsig igen\nsikker på\ngaden!",
    ["_SaffronCityTrainerTips1Text"] = "TIPS TIL TRÆNERE\nHYPERHELBREDER\nkurerer alle\nskader.\nDen er dyr,\nmen til gengæld\nmeget praktisk.",
    ["_SaffronCityTrainerTips2Text"] = "TIPS TIL TRÆNERE\nSUPERBALDEN\nøger\nfangstchancen.\nPrøv den på\nPOKéMON, der er\nsvære at fange!",
    ["_SaffronGateGuardGeeImThirstyText"] = "Jeg står vagt\nher.\nOhhh... Jeg er\nså tørstig...\nStop! Hold op!\nPassagen\ner spærret!",
    ["_SaffronGateGuardImParchedText"] = "Jeg er ved at\ntørste ihjel...\nHvad? Drikken\ner til mig?\nMange tak!",
    ["_SaffronGateGuardThanksForTheDrinkText"] = "Hej! Tak for\nden forfriskning!",
    ["_SaffronGateGuardYouCanGoOnThroughText"] = "\nGluk, gluk!\nBøvs...\nUndskyld!\nHvis du vil\ntil SAFFRON\nCITY, må du\npassere!\nJeg vil give\nlidt til de\nandre vagter!",
    ["_SaffronGymChanneler1AfterBattleText"] = "Er to modstandere\nlige stærke, vil\nden mere\nbeslutsomme\nkæmper vinde!\nHvis du vil\nbesejre SABRINA,\nkoncentrer dig\nom sejren!",
    ["_SaffronGymChanneler1BattleText"] = "SABRINA er\nyngre end mig.\nAlligevel har\njeg respekt for\nhende!",
    ["_SaffronGymChanneler1EndBattleText"] = "\nJeg er ikke\ngod nok!",
    ["_SaffronGymChanneler2AfterBattleText"] = "Mine POKéMON\nskal lære\nstærkere angreb!",
    ["_SaffronGymChanneler2BattleText"] = "POKéMON\ntilpasser sig\nderes træner.\nDine POKéMON\nmå derfor\nvære meget\nseje!",
    ["_SaffronGymChanneler2EndBattleText"] = "Jeg\nvidste det!",
    ["_SaffronGymChanneler3AfterBattleText"] = "Jeg anede, at\ndet ville ske!",
    ["_SaffronGymChanneler3BattleText"] = "Dig mod mig!\nVores POKéMON\nskal kæmpe!",
    ["_SaffronGymChanneler3EndBattleText"] = "\nJeg har alligevel\ntabt!",
    ["_SaffronGymGuideBeatSabrinaText"] = "PSYKOKINESE?\nHavde jeg\nden, ville jeg\nblive rig i\nspillehallen!",
    ["_SaffronGymGuideChampInMakingText"] = "Hey! Vent, du\nkommende champion!\nSABRINAS\nPOKéMON bruger\nPSYKOKINESE\ni stedet for\nfysiske\nkræfter!\nKAMP-POKéMON\ner ikke\nmodstandsdygtige\nover for\nPSYKOKINESE!\nDe har ikke\nengang skyggen\naf en chance!",
    ["_SaffronGymSabrinaMarshBadgeInfoText"] = "SUMP-ORDENEN\nlader POKéMON op\ntil level 70\nfølge dine\nordrer!\nStærkere POKéMON\nkunne modsætte\nsig og ignorere\ndine ordrer!\nSørg for at\nhave kontrol\nover dine POKéMON\ntil enhver tid!\nVent! Tag også\ndenne TM fra mig!",
    ["_SaffronGymSabrinaPostBattleAdviceText"] = "Teoretisk\nkunne alle lære\nPSYKOKINESE. Mange\nved bare ikke\ndet!",
    ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "Jeg er\nrystet!\nMen tabt er\ntabt.\nJeg må tilstå,\njeg anstrengte\nmig ikke alt\nfor meget!\nJeg giver dig\nSUMP-ORDENEN!",
    ["_SaffronGymSabrinaReceivedTM46Text"] = "{PLAYER} modtager\nTM46!",
    ["_SaffronGymSabrinaTM46NoRoomText"] = "Din rygsæk\ner for fuld!",
    ["_SaffronGymSabrinaText"] = "En vision\nforudsagde mig\ndin ankomst!\nJeg har mestret\nPSYKOKINESE,\nsiden jeg var\nbarn.\nFørst lærte jeg\nat bøje skeer\nmed\nPSYKOKINESE.\nJeg afskyr\nkamp!\nMen hvis du\nønsker det, viser\njeg dig mine\nkræfter!",
    ["_SaffronGymYoungster1AfterBattleText"] = "PSYKO-POKéMON\nfrygter kun\ninsekter og\nspøgelser!",
    ["_SaffronGymYoungster1BattleText"] = "Gør vores\nPSYKISKE KRÆFTER\ndig bange?",
    ["_SaffronGymYoungster1EndBattleText"] = "Jeg\ntror det ikke:\nJeg har tabt!",
    ["_SaffronGymYoungster2AfterBattleText"] = "SABRINA har\nbesejret KARATE-\nMESTEREN i\narenaen ved\nsiden af!",
    ["_SaffronGymYoungster2BattleText"] = "Du ved, at man\nikke kommer\nlangt med styrke\nalene, ikke?",
    ["_SaffronGymYoungster2EndBattleText"] = "Det \ner ufatteligt!",
    ["_SaffronGymYoungster3AfterBattleText"] = "I SAFFRON CITY\nvar der to\nPKMN-ARENAER.\nMen KAMP-DOJOEN\nhar mistet sin\nstatus som\nPKMN-ARENA, fordi\nvi har besejret\ntrænerne!",
    ["_SaffronGymYoungster3BattleText"] = "Selvom SABRINA\nstadig er ung,\ner hun vores\nARENALEDER!\nVi lader dig\nikke bare\ngå hen til hende!",
    ["_SaffronGymYoungster3EndBattleText"] = "Jeg har\nmistet\nkoncentrationen!",
    ["_SaffronGymYoungster4AfterBattleText"] = "Jeg har læst\ndine tanker!",
    ["_SaffronGymYoungster4BattleText"] = "POKéMON'ene i\nSAFFRON CITYs\nARENA er kendt\nfor deres\novernaturlige\nkræfter!\nJeg ved, at du\nvil udfordre\nSABRINA!",
    ["_SaffronGymYoungster4EndBattleText"] = "Arrrgh!",
    ["_SaffronMartCooltrainerFText"] = "REVIVER er nok\ndyr, men\nbesejrede POKéMON\nbliver friske\nigen med den!",
    ["_SaffronMartSuperNerdText"] = "TOP-SKJOLD holder\nsvage POKéMON\nlængere væk fra\ndig end\nSUPERSKJOLD!",
    ["_SaffronPidgeyHouseBrunetteGirlText"] = "...mange tak\nfor dit brev!\nVi ses snart...\nHey! Læs ikke\nmit brev!",
    ["_SaffronPidgeyHousePaperText"] = "Jeg fik en\nAP-PLUS foræret!\nDen øger\nANGREBSPOINTENE\nfor et angreb!",
    ["_SaffronPidgeyHousePidgeyText"] = "PIDGEY: Taubsi!",
    ["_SaffronPidgeyHouseYoungsterText"] = "Jeg kan lide\nEFTERLIGNEREN!\nJeg køber hende\nen POKéDUKKE!",
    ["_SaffronPokecenterBeautyText"] = "Tidspunktet\nfor udviklingen\ner forskelligt\nfra POKéMON\ntil POKéMON.",
    ["_SaffronPokecenterGentlemanText"] = "SILPH CO. er\nmeget kendt.\nDerfor blev TEAM\nROCKET\nopmærksom på\ndem!",
    ["_SandshrewDexEntry"] = "Denne POKéMON\nlever i tørre\nområder under\njorden. Den\njager dog på\njordoverfladen.",
    ["_SandslashDexEntry"] = "Ved fare ruller\ndette POKéMON\nsig sammen.\nSammenrullet\nkan det angribe\neller flygte.",
    ["_SaveOptionText"] = "I MENUEN kan du\nunder GEM\ngemme dit\nspil.",
    ["_SavingEnergyText"] = "{USER}\nsamler kræfter!",
    ["_ScaredText"] = "{RAM:wBattleMonNick} kan\nikke bevæge sig\naf skræk!",
    ["_ScytherDexEntry"] = "Denne POKéMON\ner hurtig og\nsmidig som\nen ninja. Man\ntror, man ser\nflere modstandere.",
    ["_SeadraDexEntry"] = "Denne POKéMON\nkan svømme baglæns\nved at bruge\nvinger og hale\nsom finner.",
    ["_SeafoamIslandsB4FArticunoBattleText"] = "Jauul!",
    ["_SeafoamIslandsB4FBouldersSignText"] = "Klipper kunne\nmåske omdirigere\nstrømmen!",
    ["_SeafoamIslandsB4FDangerSignText"] = "PAS PÅ!\nFARLIG\nSTRØM!",
    ["_SeakingDexEntry"] = "Om efteråret, i\nparringstiden,\nser man disse\nPOKéMON kraftfuldt\nsvømme op ad\nbække og floder.",
    ["_SeelDexEntry"] = "Denne POKéMON\nhar et meget\nhårdt horn\ntil at bryde\ntykke islag\nmed.",
    ["_SentToBoxText"] = "Der er ikke\nplads nok til\nPOKéMONen!\n{RAM:wBoxMonNicks} blev\noverført via PC\ntil POKéMON-\nBOKS {RAM:wStringBuffer}!",
    ["_ShallWeHealYourPokemonText"] = "Skal vi helbrede\ndine POKéMON?",
    ["_ShellderDexEntry"] = "Et hårdt skal\nbeskytter denne\nPOKéMON.\nKun når det\nåbner det, bliver\ndet sårbart.",
    ["_ShroudedInMistText"] = "{USER}\ner indhyllet i tåge!",
    ["_SilphCo10FGiovanniILostAgainText"] = "Arrgh!\nTabt igen!",
    ["_SilphCo10FPorygonText"] = "På skærmen\nkan man se\nPOKéMON!",
    ["_SilphCo10FRocketAfterBattleText"] = "Godt forsøg!\nMødelokalet\nbefinder sig\ndog stadig et\nstokverk\nhøjere oppe!",
    ["_SilphCo10FRocketBattleText"] = "Velkommen til\n9. etage! Det\ner sødt, at du\nkigger forbi!",
    ["_SilphCo10FRocketEndBattleText"] = "Jeg er\nchokeret!",
    ["_SilphCo10FScientistAfterBattleText"] = "Glæder det dig\nat have besejret\nmig? Mand, skrid\nendelig!",
    ["_SilphCo10FScientistBattleText"] = "Nok af dine\ndumme spilleri!",
    ["_SilphCo10FScientistEndBattleText"] = "Mine\nreserver er\nudtømt!",
    ["_SilphCo10FSilphWorkerFImScaredText"] = "Hjælp!\nJeg er bange!",
    ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "Fortæl venligst\ningen, at\njeg har grædt!",
    ["_SilphCo11FBeautyText"] = "SEKRETÆR: Vi\ntakker dig for\ndit heltemod!\nDu har reddet\nos alle! Tak!",
    ["_SilphCo11FGiovanniText"] = "Ah, {PLAYER}!\nSå mødes vi\nigen!\nJeg fører netop\nudtrykkelig\nvigtige\nforhandlinger med\nPRÆSIDENTEN.\nHold dig for\nengang for alle\nude af voksnes\nanliggender!\nEllers lærer\ndu en verden\nfuld af smerte\nat kende!",
    ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "Forbandet\nlort! Du har\nødelagt vores\novertagelse af\nSILPH CO.!\nMen TEAM\nROCKET vil\naldrig give op!\n{PLAYER}! Glem\nikke, at alle\nPOKéMON kun er\ntil nytte for\nTEAM ROCKET!\nJeg må gå,\nmen min tid\nvil komme!",
    ["_SilphCo11FRocket1AfterBattleText"] = "Vil du altså\ntil CHEFEN?",
    ["_SilphCo11FRocket1BattleText"] = "Stop! Ikke et\nskridt videre!",
    ["_SilphCo11FRocket1EndBattleText"] = "Vær sød!\nSkån mig...",
    ["_SilphCo11FRocket2AfterBattleText"] = "Vores CHEFS\nPOKéMON vil\ngøre det af\nmed dig! ",
    ["_SilphCo11FRocket2BattleText"] = "Stop! Har du\nen aftale\nmed CHEFEN?",
    ["_SilphCo11FRocket2EndBattleText"] = "OK! Jeg\nlader dig komme\nigennem!",
    ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "PRÆSIDENT: Man\nkan ikke købe\nden nogen steder!\nDet er\ndet strengt\nhemmelige\nprototype af\nMESTERBALDEN!\nMed den kan du\nfange ETHVERT\nPOKéMON VED\n1. FORSØG!\nOvervej dog\nomhyggeligt,\nhvornår du\nbruger den!",
    ["_SilphCo11FSilphPresidentNoRoomText"] = "Du har ikke\nmere plads!",
    ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "{PLAYER} modtager\nen {RAM:wStringBuffer}!",
    ["_SilphCo11FSilphPresidentText"] = "PRÆSIDENT: Jeg\ntakker dig for\nat redde\nSILPH CO.\nJeg vil aldrig\nglemme, hvordan\ndu modigt reddede\nos trods den\nstore fare!\nHvordan kan jeg\nudtrykke min\ntaknemmelighed?\nJeg er rig,\njeg kunne give\ndig alt!\nMen måske\ner den her mere\nnoget for dig!",
    ["_SilphCo1FLinkReceptionistText"] = "Velkommen!\nPRÆSIDENTEN\nbefinder sig\npå 10. etage i\nmødelokalet!",
    ["_SilphCo2FRocket1AfterBattleText"] = "De\ndiamantformede\nfelter er\nteleportere!\nEn slags high-\ntech-transportsystem!",
    ["_SilphCo2FRocket1BattleText"] = "Hey, du har\nikke noget at\ngøre her!",
    ["_SilphCo2FRocket1EndBattleText"] = "Det er\nhårdt! Tabt!",
    ["_SilphCo2FRocket2AfterBattleText"] = "SILPH CO. og\nTEAM ROCKET\nvil snart\nfusionere!",
    ["_SilphCo2FRocket2BattleText"] = "Hey, lille ven!\nHvad laver du her?",
    ["_SilphCo2FRocket2EndBattleText"] = "Jeg er\nen taber!",
    ["_SilphCo2FScientist1AfterBattleText"] = "Jeg er en spion\nog infiltrerer\nSILPH CO.!",
    ["_SilphCo2FScientist1BattleText"] = "Hjælp! Jeg er\nen medarbejder\ni SILPH CO.!",
    ["_SilphCo2FScientist1EndBattleText"] = "Hvordan\nvidste du, at\njeg tilhører TEAM\nROCKET?",
    ["_SilphCo2FScientist2AfterBattleText"] = "Men finder du\nogså vej gennem\ndenne labyrint?",
    ["_SilphCo2FScientist2BattleText"] = "Skrid! Du har\nikke adgang!",
    ["_SilphCo2FScientist2EndBattleText"] = "\nIkke dårligt,\nmin ven!",
    ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "{PLAYER} modtager\n{RAM:wStringBuffer}!",
    ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "TM36 er\nSIDSTE UDVEJ!\nEt ødelæggende\nangreb! Men det\nPOKéMON, der\nudfører det,\nudgår!!!",
    ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "Du kan ikke\nbære mere!!!",
    ["_SilphCo3FRocketAfterBattleText"] = "Et tip? Du\nhar brug for en\nNØGLEKORTET!",
    ["_SilphCo3FRocketBattleText"] = "Hold op med at\nirritere os!",
    ["_SilphCo3FRocketEndBattleText"] = "\nJeg giver op!",
    ["_SilphCo3FScientistAfterBattleText"] = "Pokkers...\nTEAM ROCKET\nville have ladet\nmig studere\nPOKéMON for min\nhjælp!",
    ["_SilphCo3FScientistBattleText"] = "Jeg arbejder for\nTEAM ROCKET,\nSILPH CO. betaler\nfor lidt!!!",
    ["_SilphCo3FScientistEndBattleText"] = "Du har\ntaget mig!",
    ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "Jeg arbejder for\nSILPH CO.!\nHvad skal jeg\ndog gøre?",
    ["_SilphCo3FSilphWorkerMYouSavedUsText"] = "{PLAYER}! Du har\nreddet os med\nhjælp fra\ndine POKéMON!",
    ["_SilphCo4FRocket1AfterBattleText"] = "På dette øjeblik\nhar chefen ventet\nmeget længe!",
    ["_SilphCo4FRocket1BattleText"] = "TEAM ROCKET\nhar overtaget\nkontrollen over\nSILPH CO.!!!",
    ["_SilphCo4FRocket1EndBattleText"] = "Arrgh!",
    ["_SilphCo4FRocket2AfterBattleText"] = "Jeg må advare\nCHEFEN på\n9. etage!",
    ["_SilphCo4FRocket2BattleText"] = "Indtrænger\nobserveret!",
    ["_SilphCo4FRocket2EndBattleText"] = "Hvem eller\nhvad er du?",
    ["_SilphCo4FScientistAfterBattleText"] = "Dørene er\nelektronisk\nlåst! Uden\nNØGLEKORTET\nkommer man ikke\nigennem!",
    ["_SilphCo4FScientistBattleText"] = "Mit POKéMON\nventer dig!!!",
    ["_SilphCo4FScientistEndBattleText"] = "Dit\nsvage POKéMON!\nPokkers!",
    ["_SilphCo4FSilphWorkerMImHidingText"] = "Pst! Kan du\nikke se, at jeg\ngemmer mig?",
    ["_SilphCo4FSilphWorkerMTeamRocketIsGoneText"] = "Er TEAM ROCKET\nforsvundet?",
    ["_SilphCo5FPokemonReport1Text"] = "En ARTIKEL om\nPOKéMON!\nPORYGON!\nPKMN-LABORATORIET\nSKABER VIRTUELT\nPOKéMON!",
    ["_SilphCo5FPokemonReport2Text"] = "Et studie om\nPOKéMON!\nDer findes mere\nend 160\nPOKéMON-\nkampteknikker!",
    ["_SilphCo5FPokemonReport3Text"] = "En rapport om \nPOKéMON!\nFire POKéMON\nudvikler sig\nkun ved bytte\nvia Link-kablet!",
    ["_SilphCo5FRockerAfterBattleText"] = "Det er langt\ntil CHEFEN! Du\ner kun på\n4. etage her!",
    ["_SilphCo5FRockerBattleText"] = "Hvaaad? Hvem\nhar dog lukket\nbarnet ind?",
    ["_SilphCo5FRockerEndBattleText"] = "Nej!\nBarnet har\nbesejret mig!",
    ["_SilphCo5FRocket1AfterBattleText"] = "Det var meget\ndumt at lægge\nsig ud med TEAM\nROCKET!",
    ["_SilphCo5FRocket1BattleText"] = "Jeg hørte, et\nbarn løber\nrundt i\nbygningen...",
    ["_SilphCo5FRocket1EndBattleText"] = "\nSlut! Forbi!",
    ["_SilphCo5FRocket2AfterBattleText"] = "Nu husker jeg,\nKOFFING udvikler\nsig til WEEZING!",
    ["_SilphCo5FRocket2BattleText"] = "Vis venligst\nTEAM ROCKET\nmere respekt!!!",
    ["_SilphCo5FRocket2EndBattleText"] = "Host...\nHost...",
    ["_SilphCo5FScientistAfterBattleText"] = "Vores nyeste\nopfindelse er\nen BALL, der\nfanger alt!",
    ["_SilphCo5FScientistBattleText"] = "Vi udvikler nye\nPOKéBALLE i\ndisse laboratorier!",
    ["_SilphCo5FScientistEndBattleText"] = "Finito!\nDet var det!",
    ["_SilphCo5FSilphWorkerMThatsYouRightText"] = "En indtrænger\nroder med TEAM\nROCKET... Det\ner dig, ikke?",
    ["_SilphCo5FSilphWorkerMYoureOurHeroText"] = "TEAM ROCKET\ner flygtet!\nDu er en helt!",
    ["_SilphCo6FRocket1AfterBattleText"] = "Ligegyldigt! Mine\nbrødre vil\nhævne mig!",
    ["_SilphCo6FRocket1BattleText"] = "Jeg er en af\nde fire berygtede\nROCKET-BRØDRE!",
    ["_SilphCo6FRocket1EndBattleText"] = "Nej!\nJeg er ude!",
    ["_SilphCo6FRocket2AfterBattleText"] = "Hvis du er ærlig\nog retskaffen,\nbekæmper du\ndet onde!",
    ["_SilphCo6FRocket2BattleText"] = "Vover du at\nsætte dig op\nimod TEAM ROCKET?",
    ["_SilphCo6FRocket2EndBattleText"] = "Din\nusle forræder!",
    ["_SilphCo6FScientistAfterBattleText"] = "TIKSI? Det\nligger dybt i\ningenmandsland!",
    ["_SilphCo6FScientistBattleText"] = "Denne forbandede\nPRÆSIDENT!\nHvorfor vil han\nnetop sende\nmig til TIKSI?",
    ["_SilphCo6FScientistEndBattleText"] = "Pokkers!",
    ["_SilphCo6FSilphWorkerF1HaveToMarryHimText"] = "Jeg tror, jeg\nvil gifte mig\nmed ham af\nmedlidenhed!",
    ["_SilphCo6FSilphWorkerF1SuchACowardText"] = "Se ham dog,\nden kujon!",
    ["_SilphCo6FSilphWorkerF2TeamRocketConquerWorldText"] = "TEAM ROCKET\nbruger POKéMON\ni forsøget på at\nerobre verden!",
    ["_SilphCo6FSilphWorkerF2TeamRocketRanText"] = "Du har jaget\nTEAM ROCKET\npå flugt!",
    ["_SilphCo6FSilphWorkerM1BackToWorkText"] = "OK, arbejdet\nkalder! Så går det løs!",
    ["_SilphCo6FSilphWorkerM1TookOverTheBuildingText"] = "TEAM ROCKET\nhar overtaget\nkontrollen over\nbygningen!",
    ["_SilphCo6FSilphWorkerM3TargetedSilphText"] = "De må have\nudset sig SILPH CO.\npå grund af\nvores POKéMON-\nprodukter!",
    ["_SilphCo6FSilphWorkerM3WorkForSilphText"] = "Vi ville blive\nmeget glade, hvis\ndu en dag skulle\narbejde for\nSILPH CO.!",
    ["_SilphCo6FSilphWorkerMHelpMePleaseText"] = "Åh nej, åh nej!\nHjælp mig venligst!",
    ["_SilphCo6FSilphWorkerMWeGotEngagedText"] = "Vi er\nforlovede!",
    ["_SilphCo7FRivalDefeatedText"] = "Mand!\nDu er så\ngod, at du kan\ntage kampen op\nmed ROCKET-CHEFEN!",
    ["_SilphCo7FRivalGoodLuckToYouText"] = "Nå, {PLAYER}!\nJeg drager\nvidere nu!\nNår jeg ser i\nPOKéDEXEN,\nser jeg, hvor\nstærke POKéMON\ner, og hvordan de\nudvikler sig!\nJeg vil tage\ntil PKMN-Ligaen.\nSå vil jeg\nudkonkurrere\nTOP FIRE!\nSnart er jeg\nverdens mest\nmagtfulde\ntræner!\nHeld og lykke,\n{PLAYER}! Og\ntræn bare\nvidere! Ciao!",
    ["_SilphCo7FRivalText"] = "{RIVAL}: Hvad har\nholdt dig tilbage,\n{PLAYER}?",
    ["_SilphCo7FRivalVictoryText"] = "{RIVAL}: Hvad skal\njeg dog sige?\nTøsedrenge\nhører ikke\nhjemme her! Gå\nhellere ud og\ntræn!",
    ["_SilphCo7FRivalWaitedHereText"] = "{RIVAL}: Hahaha!\nJeg vidste, du\nville komme\nforbi her!\nJeg vil tro,\nTEAM ROCKET har\ngjort livet\nsvært for dig!\nJeg så dig i\nSAFFRON CITY\nog spekulerede\npå, om du var\nblevet bedre\nsiden da!",
    ["_SilphCo7FRocket1AfterBattleText"] = "Hvis du bare\nløber sådan\nrundt, finder\ndu aldrig CHEFEN!",
    ["_SilphCo7FRocket1BattleText"] = "Du er\nganske modig!",
    ["_SilphCo7FRocket1EndBattleText"] = "\nLyset slukket!",
    ["_SilphCo7FRocket2AfterBattleText"] = "Vent bare, mine\nbrødre vil\nhævne mig!!!",
    ["_SilphCo7FRocket2BattleText"] = "Jeg er en af\nde fire berygtede\nROCKET-BRØDRE!",
    ["_SilphCo7FRocket2EndBattleText"] = "Undskyld,\nbrødre...",
    ["_SilphCo7FRocket3AfterBattleText"] = "Gå hjem, før\nmin CHEF\nstamper dig ned\ni jorden!",
    ["_SilphCo7FRocket3BattleText"] = "Et barn i\nbygningen? Det\nmå være dig!",
    ["_SilphCo7FRocket3EndBattleText"] = "Nå, fedt!\nJeg har tabt!",
    ["_SilphCo7FScientistAfterBattleText"] = "Knap tør bag\nørerne, men\nallerede en\ntalentfuld træner!",
    ["_SilphCo7FScientistBattleText"] = "Haha!\nTroede du vel,\njeg arbejder for\nSILPH CO.?",
    ["_SilphCo7FScientistEndBattleText"] = "\nFyraften! Jeg\ngår hjem!",
    ["_SilphCo7FSilphWorkerM1HaveThisPokemonText"] = "Åh! Du er ikke\nfra ROCKET! Kommer\ndu for at redde\nos? Fantastisk!\nMange tak! Tag\ndette POKéMON\nsom en tak.",
    ["_SilphCo7FSilphWorkerM1IsOurPresidentOkText"] = "TEAM ROCKETS\nCHEF gik ind i\nmødelokalet! Mon\nvores PRÆSIDENT\nhar det godt?",
    ["_SilphCo7FSilphWorkerM1LaprasDescriptionText"] = "Det hedder LAPRAS\nog er meget\nintelligent.\nDet har hidtil\nlevet hos os i\nlaboratoriet. Men\nhos dig er det\nbedre passet på!\nDu vil sikkert\nvære en god\ntræner for LAPRAS!\nDet er en god\nsvømmer og\nkan bære dig\nover vandet!",
    ["_SilphCo7FSilphWorkerM1SavedText"] = "Endelig befriet!\nJeg takker dig!",
    ["_SilphCo7FSilphWorkerM2AfterTheMasterBallText"] = "TEAM ROCKET\ner ude efter\nMESTERBALDEN,\nsom man kan\nfange ethvert\nPOKéMON med!",
    ["_SilphCo7FSilphWorkerM2CancelledMasterBallText"] = "Vi har stoppet\nprojektet.\nMESTERBALDEN\ni TEAM ROCKETS\nhænder? Aldrig!",
    ["_SilphCo7FSilphWorkerM3ItWouldBeBadText"] = "Det ville være\nfatalt, hvis\nTEAM ROCKET\novertog SILPH CO.\neller vores\nPOKéMON!",
    ["_SilphCo7FSilphWorkerM3YouChasedOffTeamRocketText"] = "Wow! Har du helt\nalene klaret\nTEAM ROCKET?",
    ["_SilphCo7FSilphWorkerM4ItsReallyDangerousHereText"] = "Her er det meget\nfarligt! Du\nvil ikke kunne\nredde mig!",
    ["_SilphCo7FSilphWorkerM4SafeAtLastText"] = "Endelig reddet!\nJeg takker dig!",
    ["_SilphCo8FRocket1AfterBattleText"] = "Skrid hellere,\nellers tilkalder\njeg forstærkning!",
