    ["_SilphCo8FRocket1EndBattleText"] = "Pokkers, \nmodet har\nforladt mig!",
    ["_SilphCo8FRocket2AfterBattleText"] = "Så vil mine\nbrødre tage\nsig af dig!",
    ["_SilphCo8FRocket2BattleText"] = "Jeg er en af\nde fire berygtede\nROCKET-BRØDRE!",
    ["_SilphCo8FRocket2EndBattleText"] = "Ups!\nBrødre, jeg har\nfejlet!",
    ["_SilphCo8FScientistAfterBattleText"] = "SILPH CO.-\nbygningen er en\nsand labyrint,\nikke sandt?",
