    ["_VermilionCityNoticeSignText"] = "PAS PÅ!\nRUTE 12 er\nspærret af en\nsovende\nPOKéMON.\nOmkørsel: \nKLIPPETUNNELEN til\nLAVENDER TOWN.\nPOLITIET I\nVERMILION CITY",
