    ["_VermilionGymGentlemanEndBattleText"] = "Stop!\nDu er for god!",
    ["_VermilionGymGymGuideBeatLTSurgeText"] = "Puh! Sikke\nen elektrisk\nkamp!",
    ["_VermilionGymGymGuideChampInMakingText"] = "Hey! Vent, du\nkommende champion!\nLT. SURGE har\net kælenavn.\nMan kalder ham\nden LYNHURTIGE\nARENALEDER!\nHan er\nekspert i\nELEKTRO-POKéMON!\nFUGLE- og\nVAND-POKéMON\ner hjælpeløse\nover for ham! Han\nbruger også\ngerne PARALYSE!\nLT. SURGE er\nmeget forsigtig!\nDu skal løse\net gåde for at\ntræffe ham!",
    ["_VermilionGymLTSurgePostBattleAdviceText"] = "Jeg giver dig\nendnu et tip,\nunge mand!\nElektricitet\ner enormt\nkraftfuld!\nMen den har\ningen virkning på\nJORD-POKéMON!",
    ["_VermilionGymLTSurgePreBattleText"] = "Hey, lille ven!\nHvad har du\nmistet her?\nI kamp har\ndu ingen\nstor chance,\ndet er sikkert!\nLad mig fortælle\ndig noget: \nUnder\nPOKéMON-FELTTOGENE\nreddede mine\nELEKTRO-POKéMON\nmig!\nDe paralyserede\nmine modstandere\nmed strøm!",
    ["_VermilionGymLTSurgeReceivedTM24Text"] = "{PLAYER} modtager\n{RAM:wStringBuffer}!",
    ["_VermilionGymLTSurgeReceivedThunderBadgeText"] = "Wow!\nDu ved, hvordan\nman kæmper, lille ven!\nSom anerkendelse\ngiver jeg dig\nTORDEN-ORDENEN!",
    ["_VermilionGymLTSurgeTM24NoRoomText"] = "Din rygsæk\ner fuld!",
    ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "TORDEN-ORDENEN\nøger dine\nPOKéMONs\nINITIATIV!\nDesuden kan\ndine POKéMON nu\nbruge FLYVE\ntil enhver tid!\nDu er en\nsærlig dreng!\nTag den her!",
    ["_VermilionGymSailorAfterBattleText"] = "LT. SURGE har\nsikret døren\ndobbelt!\nEt tip? Den\nanden kontakt\ner lige ved\nsiden af den\nførste!",
    ["_VermilionGymSailorBattleText"] = "Dette her er\nikke en legeplads!",
    ["_VermilionGymSailorEndBattleText"] = "Wow!\nDu overraskede\nmig!",
    ["_VermilionGymSuperNerdAfterBattleText"] = "OK, jeg taler!\nLT. SURGE har\ngemt kontakter\nher et sted!",
    ["_VermilionGymSuperNerdBattleText"] = "Jeg er en\nfluevægt,\nmen i omgangen\nmed elektricitet\ner jeg en proff!",
    ["_VermilionGymSuperNerdEndBattleText"] = "En\nkortslutning!",
    ["_VermilionGymTrashFailText"] = "Ingenting! Her\ner kun affald...\nHey! Låsen\ner blevet\nlåst igen!",
    ["_VermilionGymTrashSuccessText1"] = "Hey! Her er et\nhåndtag skjult!\nJeg vil\nbetjene det!\nDen første lås\nblev åbnet!",
    ["_VermilionGymTrashSuccessText2"] = "Her er endnu et\nhåndtag gemt\nunder affaldet!\nJeg betjener det!",
