    ["_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText"] = "Hej, {PLAYER}!\nBider fiskene\ngodt på?",
    ["_VermilionOldRodHouseFishingGuruNoRoomText"] = "Åh nej!\nDu har ikke\nplads til min\ngave!",
    ["_VermilionOldRodHouseFishingGuruTakeThisText"] = "Fedt! Jeg kan\nrigtig lide dig!\nTag den her\nog gå på fisketur,\nunge ven!\n{PLAYER} modtager\nen {RAM:wStringBuffer}!",
    ["_VermilionOldRodHouseFishingGuruThatsSoDisappointingText"] = "Åh... Det er\nvirkelig ærgerligt!",
    ["_VermilionPidgeyHouseLetterText"] = "Kære NIKKI! Jeg\nhåber, vi ses\nigen snart!\nSom jeg hører\ndet, skaber TEAM\nROCKET uro i\nSAFFRON CITY!\nI VERMILION CITY\nser det ud til\nat være sikkert.",
    ["_VermilionPidgeyHousePidgeyText"] = "PIDGEY: Taubsi!",
    ["_VermilionPidgeyHouseYoungsterText"] = "Jeg lader PIDGEY\nbringe et brev\ntil SAFFRON CITY\ni nord!",
    ["_VermilionPokecenterFishingGuruText"] = "Selv med samme\nlevel kan\nPOKéMONs evner\nstadig være\nforskellige.\nEt træners POKéMON\ner stærkere end\net vildtlevende.",
    ["_VermilionPokecenterGuyText"] = "Det er sandt,\nat en POKéMON\nmed et højt\nlevel er meget\nstærk...\nMen alle\nPOKéMON har\nsvagheder. Det\nrette angreb\nkan let besejre\ndem!\nDerfor findes\nder intet\nuniversal-POKéMON.",
    ["_VermilionPokecenterSailorText"] = "Mit POKéMON\nblev forgiftet!\nGiften besejrede\ndet længe efter\nkampen!",
    ["_VictoryRoad1FCooltrainerFAfterBattleText"] = "Og jeg ville\naldrig tabe!",
    ["_VictoryRoad1FCooltrainerFBattleText"] = "Tror du, du\nkan tage kampen\nop med mig?",
    ["_VictoryRoad1FCooltrainerFEndBattleText"] = "Jeg\ner ude!",
    ["_VictoryRoad1FCooltrainerMAfterBattleText"] = "Jeg må indrømme,\ndu er bedre!",
    ["_VictoryRoad1FCooltrainerMBattleText"] = "Jeg tror, du\ner god! Godt\nnok til at\nslå mig?",
    ["_VictoryRoad1FCooltrainerMEndBattleText"] = "I det mindste\nhavde jeg en\nchance!",
    ["_VictoryRoad2FCooltrainerMAfterBattleText"] = "Du følger\nSEJRSVEJEN\nikke uden grund!",
    ["_VictoryRoad2FCooltrainerMBattleText"] = "Kom bare her!\nJeg vil besejre\ndig!",
    ["_VictoryRoad2FCooltrainerMEndBattleText"] = "Auweia!\nJeg er besejret!",
    ["_VictoryRoad2FHikerAfterBattleText"] = "Hvis du ikke\nkommer videre,\nprøv at\nflytte\nklipperne!",
    ["_VictoryRoad2FHikerBattleText"] = "SEJRSVEJEN\nudgør en slags\nafsluttende\nprøve for\ntrænere!",
    ["_VictoryRoad2FHikerEndBattleText"] = "Ahh! ",
    ["_VictoryRoad2FMoltresBattleText"] = "Jauuul!",
    ["_VictoryRoad2FSuperNerd1AfterBattleText"] = "Også {RIVAL}\nkom forbi her!",
    ["_VictoryRoad2FSuperNerd1BattleText"] = "Vil du altså\nudfordre TOP\nFIRE?",
    ["_VictoryRoad2FSuperNerd1EndBattleText"] = "Fuldt\nramt!",
    ["_VictoryRoad2FSuperNerd2AfterBattleText"] = "Og selv hvis...\nSå overstiger min\nviden om POKéMON\ndin langt.",
    ["_VictoryRoad2FSuperNerd2BattleText"] = "Kommer du forbi\nmig, kan du\ngå videre til\nTOP FIRE!",
    ["_VictoryRoad2FSuperNerd2EndBattleText"] = "Nej!\nUtroligt!",
    ["_VictoryRoad2FSuperNerd3AfterBattleText"] = "Mange trænere\nhar allerede\ngivet op her!",
    ["_VictoryRoad2FSuperNerd3BattleText"] = "SEJRSVEJEN\ner meget svær\nat mestre!",
    ["_VictoryRoad2FSuperNerd3EndBattleText"] = "Godt\ngjort!",
    ["_VictoryRoad3FCooltrainerF1AfterBattleText"] = "Du har vist mig\nmin plads!",
    ["_VictoryRoad3FCooltrainerF1BattleText"] = "Straks vil du se,\nhvor god du er!",
    ["_VictoryRoad3FCooltrainerF1EndBattleText"] = "Det\nkan ikke være\nsandt! Grrr!",
    ["_VictoryRoad3FCooltrainerF2AfterBattleText"] = "Jo hårdere\nkampene er,\ndesto stærkere\nbliver du!",
    ["_VictoryRoad3FCooltrainerF2BattleText"] = "Trænere er\nfødte kæmpere,\naltid på\nudkig efter\nstærke modstandere!",
    ["_VictoryRoad3FCooltrainerF2EndBattleText"] = "Sejt!\nDu er virkelig\nstærk!",
    ["_VictoryRoad3FCooltrainerM1AfterBattleText"] = "Har du virkelig\nbesejret GIOVANNI\nfra TEAM ROCKET?",
    ["_VictoryRoad3FCooltrainerM1BattleText"] = "Man fortæller om\net vidunderbarn!",
    ["_VictoryRoad3FCooltrainerM1EndBattleText"] = "Du er\nvidunderbarnet!",
    ["_VictoryRoad3FCooltrainerM2AfterBattleText"] = "Trænerne her\ner på vej til\nPKMN-Ligaen!\nVær forsigtig!",
    ["_VictoryRoad3FCooltrainerM2BattleText"] = "Kun de udvalgte\nmå passere!",
    ["_VictoryRoad3FCooltrainerM2EndBattleText"] = "Jeg\nfatter det ikke!",
    ["_VictreebelDexEntry"] = "Denne POKéMON\nskal leve i store\nkolonier dybt i\njunglen, men\ningen kan\nbekræfte dette.",
    ["_VileplumeDexEntry"] = "Jo større\nkronbladene,\ndesto mere\ngiftigt pollen\ner der i\nblomsten.",
    ["_ViridianBlackboardBurnText"] = "En forbrænding\nsvækker kraft\nog styrke. KP\nfalder støt.\nForbrændinger\nvarer også ved\nefter en kamp.\nMan helbreder\ndem med\nILDHELBREDER.",
    ["_ViridianBlackboardFrozenText"] = "En frosset\nPOKéMON kan\nikke bevæge sig.\nDet bevarer også\ndenne tilstand\nefter kampen.\nKun ISHELBREDEREN\nkan tø det\nop igen!",
    ["_ViridianBlackboardPoisonText"] = "En forgiftet\nPOKéMON mister\nkonstant KP.\nGiftens virkning\nvarer også ved\nefter en kamp.\nMODGIFT\nhelbreder\nforgiftninger.",
    ["_ViridianBlackboardPrlzText"] = "En paralyseret\nPOKéMON\nmister\ntræfsikkerhed!\nParalysen varer\nogså ved efter\nen kamp.\nMan behandler den\nmed PARA-\nHELBREDER.",
    ["_ViridianBlackboardSleepText"] = "Når en POKéMON\nsover, kan det\nikke angribe!\nEt sovende\nPOKéMON vågner\nheller ikke\nefter kampen.\nBrug\nOPVÆKKER, for\nat det vågner.",
    ["_ViridianCityFisherReceivedTM42Text"] = "{PLAYER} modtager\nTM42!",
    ["_ViridianCityFisherTM42ExplanationText"] = "TM42 er\nDRØMSPISER!",
    ["_ViridianCityFisherTM42NoRoomText"] = "Du bærer for\nmange items!",
    ["_ViridianCityGambler1GymAlwaysClosedText"] = "Denne PKMN-ARENA\ner altid\nlukket!\nJeg spekulerer\npå, hvem der\nmon er\nARENALEDEREN?",
    ["_ViridianCityGambler1GymLeaderReturnedText"] = "ARENALEDEREN i\nVIRIDIAN CITY\ner tilbage!",
    ["_ViridianCityGirlHasntHadHisCoffeeYetText"] = "Bedstefar! Vær\nikke så led!\nHan har ikke\nfået kaffe endnu!!!",
    ["_ViridianCityGirlWhenIGoShopText"] = "Når jeg vil\ntage til\nPEWTER CITY\nfor at handle,\nskal jeg altid\ngennem\nVIRIDIAN-SKOVEN.",
    ["_ViridianCityGymLockedText"] = "Dørene til\nARENAEN er\nlåst...",
    ["_ViridianCityGymSignText"] = "VIRIDIAN CITY\nPKMN-ARENA",
    ["_ViridianCityOldManHadMyCoffeeNowText"] = "Ahh, jeg har\nendelig fået\nmin kaffe!\nSelvfølgelig\nmå du passere!\nHar du\ntravlt?",
    ["_ViridianCityOldManKnowHowToCatchPokemonText"] = "Aha, du bruger\nen POKéDEX!\nNår du fanger\net POKéMON,\nopdateres din\nPOKéDEX\nautomatisk.\nHvad? Ved du\nikke, hvordan\nman fanger\nPOKéMON?\nIntet problem! Jeg\nforklarer det!",
    ["_ViridianCityOldManSleepyPrivatePropertyText"] = "Du kan ikke\ngå igennem her!\nDet er\nprivat område!",
    ["_ViridianCityOldManTimeIsMoneyText"] = "Tid er penge...\nSå gå videre!",
    ["_ViridianCityOldManYouNeedToWeakenTheTargetText"] = "Vil du fange\net POKéMON,\nskal du først\nsvække det!",
    ["_ViridianCityPokecenterGuyText"] = "I PKMN-CENTERET\nkan du helbrede\ntrætte, skadede\nog besejrede\nPOKéMON!",
    ["_ViridianCitySignText"] = "VIRIDIAN CITY.\nDet evigt grønne\nparadis!",
    ["_ViridianCityTrainerTips1Text"] = "TIPS TIL TRÆNERE\nFang POKéMON\nfor at udvide\ndin samling!\nJo flere du\nejer, desto\nlettere bliver\nkampene!",
    ["_ViridianCityTrainerTips2Text"] = "TIPS TIL TRÆNERE\nPOKéMONs\nangreb\nbegrænses af\nderes\nANGREBSPOINT,\nAP.\nFor at fylde\nAP'en op igen,\nskal du bringe\nPOKéMON til et\nPOKéMON-\nCENTER!",
    ["_ViridianCityYoungster1Text"] = "Disse POKéBALLE\npå dit bælte\nviser mig, at\ndu ejer\nPOKéMON!\nDet er fedt,\nat man til\nenhver tid kan\nbære og bruge\nPOKéMON, ikke?",
    ["_ViridianCityYoungster2YouWantToKnowAboutText"] = "Vil du vide\nnoget om de to\nLARVE-POKéMON?",
    ["_ViridianForestLeavingSignText"] = "FARVEL\nFRA VIRIDIAN-SKOVEN.\nNÆSTE STED\nER PEWTER\nCITY.",
    ["_ViridianForestNorthGateGrampsText"] = "Læg mærke til\nbuske langs vejen.\nPOKéMON kan\nhugge dem ned med\nen special-\nteknik.",
    ["_ViridianForestNorthGateSuperNerdText"] = "Mange POKéMON\nlever i huler\nog skove.\nDu burde kigge\ndig omkring\noveralt for at\nfinde\nforskellige!",
    ["_ViridianForestSouthGateGirlText"] = "Går du ind i\nVIRIDIAN-SKOVEN?\nPas på, man\nfarer let vild\nder!",
    ["_ViridianForestSouthGateLittleGirlText"] = "Har du allerede\nfanget en RATTATA?\nDen er lille, men\ndens bid er\nvoldsomt!",
    ["_ViridianForestTrainerTips1Text"] = "TIPS TIL TRÆNERE\nHvis du vil\nundgå kampe,\nså hold dig\nvæk fra højt\ngræs!",
    ["_ViridianForestTrainerTips2Text"] = "TIPS TIL TRÆNERE\nDu kan altid\nfå din POKéDEX\nbedømt af\nPROF. OAK\nvia PC!",
    ["_ViridianForestTrainerTips3Text"] = "TIPS TIL TRÆNERE\nDet er forbudt\nat stjæle POKéMON\nfra andre\ntrænere! Fang\nkun vilde\nPOKéMON!",
    ["_ViridianForestTrainerTips4Text"] = "TIPS TIL TRÆNERE\nSvækkede\nPOKéMON er\nlettere at\nfange!\nEr de ved\nfulde kræfter,\nkan de flygte!",
    ["_ViridianForestUseAntidoteSignText"] = "Ved forgiftninger\nhar MODGIFT fra\nPKMN-SUPERMARKEDET\nvist sig\neffektivt.",
    ["_ViridianForestYoungster1Text"] = "Mine venner og\njeg har allerede\nventet på dig...\nVores POKéMON\nvil kæmpe!!!",
    ["_ViridianForestYoungster2AfterBattleText"] = "Psst! Vær stille!\nDu skræmmer alle\ninsekterne væk...",
    ["_ViridianForestYoungster2BattleText"] = "Hey! Du har også\nPOKéMON! Kom!\nLad os kæmpe!",
    ["_ViridianForestYoungster2EndBattleText"] = "Ah!\nCATERPIE klarede\ndet ikke!",
    ["_ViridianForestYoungster3AfterBattleText"] = "Sikke et uheld! Jeg\nmå fange et par\nstærkere!",
    ["_ViridianForestYoungster3BattleText"] = "Hey! En POKéMON-\ntræner stikker\nikke bare af!!!",
    ["_ViridianForestYoungster3EndBattleText"] = "Åh!\nJeg har ingen\nkampklare\nPOKéMON tilbage!",
    ["_ViridianForestYoungster4AfterBattleText"] = "Med lidt held\nfinder man\nitems undervejs!\nJeg må have\ntabt noget her\net sted...",
    ["_ViridianForestYoungster4BattleText"] = "Hey, vent lige!\nHvorfor så travlt?",
    ["_ViridianForestYoungster4EndBattleText"] = "Puha!\nDu er for god!\nJeg giver op!",
    ["_ViridianForestYoungster5Text"] = "Pokkers!\nJeg er løbet\ntør for\nPOKéBALLE!\nHvordan fanger\njeg nu POKéMON?\nDu burde altid\nhave nok\nPOKéBALLE med dig!",
    ["_ViridianGymCooltrainerM1AfterBattleText"] = "Du skal være\nstærk for at\ntage kampen op\nmed vores\nARENALEDER!",
    ["_ViridianGymCooltrainerM1BattleText"] = "Hehe! Nu bliver\ndu vist mør!",
    ["_ViridianGymCooltrainerM1EndBattleText"] = "Jeg\nløber tør for\nPOKéMON!!!",
    ["_ViridianGymCooltrainerM2AfterBattleText"] = "Mesteren vil\nskælde mig ud!",
    ["_ViridianGymCooltrainerM2BattleText"] = "Stilen kendetegner\nen stor\nkæmper!",
    ["_ViridianGymCooltrainerM2EndBattleText"] = "\nJeg har mistet\nfodfæstet!",
    ["_ViridianGymCooltrainerM3AfterBattleText"] = "Du kan kun\nkomme til PKMN-LIGAEN,\nhvis du besejrer\nvores\nARENALEDER!",
    ["_ViridianGymCooltrainerM3BattleText"] = "ARENAHALLEN i\nVIRIDIAN CITY\nvar længe\nlukket, men\nnu er MESTEREN\ntilbage!",
    ["_ViridianGymCooltrainerM3EndBattleText"] = "Er jeg\nblevet besejret?",
    ["_ViridianGymGiovanniEarthBadgeInfoText"] = "Som bærer af\nJORD-ORDENEN vil\nalle POKéMON på\nethvert level\nadlyde dig!\nDen er beviset\npå dine evner\nsom POKéMON-\nTRÆNER!\nDesuden giver\nden dig adgang\ntil PKMN-LIGAEN!\nTag denne gave\nmed på dit\nPKMN-LIGA-\neventyr!",
    ["_ViridianGymGiovanniPostBattleAdviceText"] = "Jeg har fundet\nmin mester!\nMine handlinger\nvar onde... Jeg\nopløser TEAM\nROCKET!\nFra nu af\nvier jeg mit\nliv til studiet\naf POKéMON!\nMåske ses vi\nen dag igen!\nFarvel!",
    ["_ViridianGymGiovanniPreBattleText"] = "Haha! Velkommen\ntil mit\nhemmelige\nskjulested!\nHer ville jeg\ngenoplive TEAM\nROCKET!\nMen du har\nallerede sporet\nmig igen!\nNå, godt! Denne\ngang kender jeg\ningen nåde!\nJeg, GIOVANNI,\nden største af\nalle trænere,\nkræver revanche!",
    ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "Ha!\nKampen var\nhård, men fair!\nDu har vundet!\nTag venligst\nJORD-ORDENEN\nsom tegn på\nmin anerkendelse!",
    ["_ViridianGymGiovanniReceivedTM27Text"] = "{PLAYER} modtager\nTM27!",
    ["_ViridianGymGiovanniTM27ExplanationText"] = "\nTM27 er\nJORDSKÆLV!\nMan kan besejre\net POKéMON\nmed bare ét\ntræf!\nJeg skabte den\nfor længe siden,\nda jeg stadig\nvar ARENALEDER\nher.",
    ["_ViridianGymGiovanniTM27NoRoomText"] = "Du kan ikke\nbære den lige\nnu!",
    ["_ViridianGymGuidePostBattleText"] = "Det kan ikke passe!\nVar GIOVANNI\nARENALEDER her?",
    ["_ViridianGymGuidePreBattleText"] = "Hey! Vent, du\nkommende champion!\nIkke engang jeg\nkender\nidentiteten på\nARENALEDEREN i\nVIRIDIAN CITY!\nSå vidt jeg ved,\ner han den\nfarligste af\nalle\nARENALEDERE!\nTrænerne her\nbruger gerne\nJORD-POKéMON!",
    ["_ViridianGymHiker1AfterBattleText"] = "Jeg er ikke\nværdig til din nåde!",
    ["_ViridianGymHiker1BattleText"] = "Kiai! Med dette\nkampskrig\nmobiliserer jeg\nmine kræfter!",
    ["_ViridianGymHiker1EndBattleText"] = "\nMester, tilgiv\nmig!",
    ["_ViridianGymHiker2AfterBattleText"] = "Ak, var mine\nPOKéMON dog også\nså stærke\nkarateudøvere\nsom jeg!",
    ["_ViridianGymHiker2BattleText"] = "Karate er\nkampsportens\nkongedisciplin!",
    ["_ViridianGymHiker2EndBattleText"] = "Av!",
    ["_ViridianGymHiker3AfterBattleText"] = "Vil du til\nPKMN-LIGAEN? Dig?\nBliv nu ikke\nstorhedsvanvittig!",
    ["_ViridianGymHiker3BattleText"] = "Jeg er\nKARATE-KONGEN!\nJeg besegler\ndin skæbne!",
    ["_ViridianGymHiker3EndBattleText"] = "Ahh!",
    ["_ViridianGymRocker1AfterBattleText"] = "Kender du\nidentiteten på\nvores ARENALEDER?",
    ["_ViridianGymRocker1BattleText"] = "Jeg danner med\nmine POKéMON\nen enhed\nsom yin og yang!",
    ["_ViridianGymRocker1EndBattleText"] = "\nDine POKéMON\nharmonerer godt\nmed dig!",
    ["_ViridianGymRocker2AfterBattleText"] = "Vent bare!\nDet vil du\nbøde for!",
    ["_ViridianGymRocker2BattleText"] = "Bare synet af\nmig får dine\nPOKéMON til\nat gyse!",
    ["_ViridianGymRocker2EndBattleText"] = "\nDe kryber sammen\naf grin! NEJ!",
    ["_ViridianMartClerkParcelQuestText"] = "PROF. OAK\nsender dig,\nikke?\nHans bestilling\ner ankommet!\nHenter du\npakken for ham?\n{PLAYER} modtager\nOAKS PAKKE!",
    ["_ViridianMartClerkSayHiToOakText"] = "OK! Hils PROF.\nOAK fra mig!",
    ["_ViridianMartClerkYouCameFromPalletTownText"] = "Hey! Kommer du\nfra PALLET TOWN?",
    ["_ViridianMartCooltrainerMText"] = "Beklager!\nAlle DRIKKE er\nudsolgt!",
    ["_ViridianMartYoungsterText"] = "Denne butik\nfører mange\nMODGIFTE.",
    ["_ViridianNicknameHouseBaldingGuyText"] = "Det er sjovt\nat finde på\nkælenavne. Men\ndet kræver meget\nfantasi!\nEnkle navne\nkan man huske\nlettere!",
    ["_ViridianNicknameHouseLittleGirlText"] = "Min far kan også\nrigtig godt lide\nPOKéMON!",
    ["_ViridianNicknameHouseSpearowText"] = "WILLI: \nHabi! Habitak!",
    ["_ViridianNicknameHouseSpearySignText"] = "SPEAROW\nKælenavn: WILLI",
    ["_ViridianPokecenterCooltrainerMText"] = "Der findes et\nPKMN-CENTER\ni hver by.\nDer behandler\nman dine POKéMON\ngratis!",
    ["_ViridianPokecenterGentlemanText"] = "Du kan bruge\nPC'en i hjørnet\nderovre!\nDet blev jeg\nvenligst gjort\nopmærksom på\ni receptionen.",
    ["_ViridianSchoolBlackboardText1"] = "Tavlen viser\nstatusændringer\nhos POKéMON\nunder kampen.",
    ["_ViridianSchoolBlackboardText2"] = "Vælg venligst et\nemneområde.",
    ["_ViridianSchoolHouseBrunetteGirlText"] = "Puh! Jeg\nprøver at lære\nmine noter\nudenad.",
    ["_ViridianSchoolHouseCooltrainerFText"] = "OK!\nLæs teksten på\ntavlen\nomhyggeligt!",
    ["_ViridianSchoolNotebookText1"] = "Du kigger i\nnotesbogen!\nFørste side...\nTil at fange\nPOKéMON bruger\nman POKéBALLE.\nMan kan bære op\ntil seks POKéMON\nad gangen.\nPOKéMON-TRÆNERE\nopdrætter POKéMON\nog træner dem.",
    ["_ViridianSchoolNotebookText2"] = "Anden side...\nEt POKéMON ved\nfuld styrke er\nsvært at fange!\nMan bør svække\ndet først.\nIld, gift og\nandre angreb\nvirker vidundere!",
    ["_ViridianSchoolNotebookText3"] = "Tredje side...\nPOKéMON-TRÆNERE\nleder efter\nhinanden og lader\nderes POKéMON\nkæmpe.\nI\nPKMN-ARENAER\nfinder der altid\nkampe sted.",
    ["_ViridianSchoolNotebookText4"] = "Fjerde side...\nMålet for enhver\nPOKéMON-TRÆNER\ner at besejre\nde otte ledere\naf PKMN-\nARENAERNE.\nKun da må han\nmøde TOP FIRE i\nPKMN-LIGAEN!",
    ["_ViridianSchoolNotebookText5"] = "PIGE: Hey! Hold\nfingrene væk fra\nmine noter!",
    ["_VitaminNoEffectText"] = "Det ville ikke\nhave nogen effekt.",
    ["_VitaminStatRoseText"] = "{RAM:wNameBuffer}s\n{RAM:wStringBuffer} er\nsteget.",
    ["_VoltorbDexEntry"] = "Denne POKéMON\nforveksles ofte\nmed en POKéBALL.\nDet lever\nfortrinsvis\ni kraftværker.",
    ["_VulpixDexEntry"] = "Denne POKéMON\nhar ved fødslen\nkun én hale,\nder deler sig\nmed stigende\nalder.",
    ["_WannaTrade1Text"] = "Jeg leder efter\n{RAM:wInGameTradeGiveMonName}!\nBytter du det\nfor {RAM:wInGameTradeReceiveMonName}?",
    ["_WannaTrade2Text"] = "Hej! Vil du ikke\nbytte dit\n{RAM:wInGameTradeGiveMonName}\nmod en\n{RAM:wInGameTradeReceiveMonName}?",
    ["_WannaTrade3Text"] = "Ejer du en\n{RAM:wInGameTradeGiveMonName}?\nVil du bytte\nden mod\n{RAM:wInGameTradeReceiveMonName}?",
    ["_WardensHouseDisplayMerchandiseText"] = "Gamle POKéMON-\nlegetøj.",
    ["_WardensHouseDisplayPhotosAndFossilsText"] = "Billeder af POKéMON\nog fossiler.",
    ["_WardensHouseWardenGaveTheGoldTeethText"] = "{PLAYER} giver\nVOGTEREN\nGULDTÆNDERNE!",
    ["_WardensHouseWardenGibberish1Text"] = "VOGTER: Hef faff\nheffee!\nHa lof ha feef ee\nhaffhe he. Heff\nhee fiee!",
    ["_WardensHouseWardenGibberish2Text"] = "Eff heffe fefe!\nEef  hafahi-fone!",
    ["_WardensHouseWardenGibberish3Text"] = "Ha? Hei heff heh\nha hef ee haheh!",
    ["_WardensHouseWardenHM04ExplanationText"] = "VOGTER: VM04\ner STYRKE!\nMed den lærer\nPOKéMON at\nflytte klipper,\nselv når de\nikke kæmper!\nHar du allerede\nfundet det\nSKJULTE HUS i\nSAFARI-\nZONEN?\nMan vinder en\nVM, hvis man\nfinder det!\nEfter sigende\ndrejer det sig om\nVM'en SURFER.",
    ["_WardensHouseWardenHM04NoRoomText"] = "Din rygsæk\ner for fuld!",
    ["_WardensHouseWardenReceivedHM04Text"] = "{PLAYER} modtager\n{RAM:wStringBuffer}!",
    ["_WardensHouseWardenTeethPoppedInHisTeethText"] = "\nVOGTEREN sætter\ngebisset i!",
    ["_WardensHouseWardenThanksText"] = "VOGTER: Tak,\nunge mand! Ingen\nhar forstået\net eneste ord\naf, hvad jeg sagde!\nSådan kunne jeg\nikke arbejde.\nTag den her\nfor din umage.",
    ["_WarpToLastPokemonCenterText"] = "Vende tilbage\ntil det sidste\nPKMN-CENTER?",
